function refreshPostControls(id){const root=$('[data-post-thread]');if(root?.dataset.postThread!==id)return;const busy=postPending.get(id),expired=meetupLifecycle(state.posts.find(p=>p.id===id),serverNow()).expired,submit=root.querySelector('.comment-submit');if(submit){submit.disabled=!!busy||expired;submit.setAttribute('aria-busy',String(!!busy));}root.querySelectorAll('[data-join],[data-delete-post]').forEach(b=>{b.disabled=!!busy||expired||b.hasAttribute('data-join')&&state.posts.find(p=>p.id===id)?.viewerJoined!==true&&!(state.posts.find(p=>p.id===id)?.joinedIds||[]).includes(viewer.id)&&(state.posts.find(p=>p.id===id)?.joinAccess?.allowed===false||meetupLifecycle(state.posts.find(p=>p.id===id),serverNow()).closed);b.setAttribute('aria-busy',String(!!busy));});}
