async function postMutation(id,kind,payload){if(shared){const r=await request('/api/posts/'+kind,{id,...payload});if(r.post)return r.post;if(kind==='join'&&payload.joined===false&&r.ok&&r.joined===false){const current=state.posts.find(x=>x.id===id);if(current){const joinedNames={...(current.joinedNames||{})};delete joinedNames[viewer.id];return {...current,viewerJoined:false,joinedIds:(current.joinedIds||[]).filter(x=>x!==viewer.id),joinedNames};}}throw Error('게시글 갱신을 확인하지 못했어요. 다시 열어주세요.');}const p=state.posts.find(p=>p.id===id);if(!p)throw Error('게시글을 찾을 수 없어요.');if(kind==='join'){p.joinedIds??=[];p.joinedNames??={};p.joinedIds=payload.joined?[...new Set([...p.joinedIds,viewer.id])]:p.joinedIds.filter(x=>x!==viewer.id);p.joinedNames[viewer.id]=state.name;}else if(!p.comments.some(c=>c.id===payload.requestId))p.comments.push({id:payload.requestId,author:state.name,authorId:viewer.id,text:payload.text});return p;}
async function participatePost(id){if(postPending.has(id))return;const p=state.posts.find(p=>p.id===id);if(!p)return;const joined=!(p.viewerJoined===true||(p.joinedIds||[]).includes(viewer.id)),root=$('[data-post-thread]'),status=root?.querySelector('.thread-status');postPending.set(id,'join');refreshPostControls(id);if(status)status.textContent='처리하고 있어요…';try{const updated=await postMutation(id,'join',{joined});if((updated.joinedIds||[]).includes(viewer.id)!==joined)throw Error('참여 상태가 반영되지 않았어요. 다시 시도해주세요.');applyThread(updated);if(status?.isConnected)status.textContent=joined?'참여했어요.':'참여를 취소했어요.';}catch(e){if(e.joinAccess){p.joinAccess=e.joinAccess;}if(status?.isConnected)status.textContent=e.message;toast(e.message);}finally{postPending.delete(id);const current=state.posts.find(x=>x.id===id);if(current&&$('[data-post-thread]')?.dataset.postThread===id)$('#thread-join').innerHTML=threadJoin(current);refreshPostControls(id);}}
async function submitCommunityComment(form){const id=form.dataset.postId,text=form.elements.text.value.trim();if(!text||postPending.has(id))return;if(form.dataset.requestText!==text){form.dataset.requestText=text;form.dataset.requestId=crypto.randomUUID();}postPending.set(id,'comment');refreshPostControls(id);const status=form.querySelector('.thread-status');status.textContent='';try{const p=await postMutation(id,'comment',{text,requestId:form.dataset.requestId});applyThread(p);if(form.elements.text.value.trim()===text)form.elements.text.value='';delete form.dataset.requestText;delete form.dataset.requestId;status.textContent='댓글을 등록했어요.';unsaved.track(form);}catch(e){status.textContent='등록하지 못했어요. 입력한 내용은 유지됩니다.';toast(e.message);}finally{postPending.delete(id);refreshPostControls(id);}}

function workoutForm(p,{copied=null}={}){
 if(!(can('workouts.create')||can('workouts.update')))return;if(isWednesday(date)&&p==='B/T')return toast('수요일에는 WOD만 등록할 수 있어요.');const w=workout(p),draft=copied?null:drafts.read(viewer.id,date,p),source=copied||draft||w;
 const sections=source.sections?.length?source.sections:[{title:'',text:'',record:false,kind:'중량',movements:[]},{title:'',text:'',record:false,kind:'중량',movements:[]}];
 const sessionText=typeof source.sessions==='string'?source.sessions:(source.sessions||[]).join(', '),overview=source.overview??(source.overviewId?'https://youtu.be/'+source.overviewId:'');
 modal(`${p} 수업 등록 · ${date}`,`<form id="workout-form" data-program="${p}" data-date="${date}" data-count="${sections.length}"><div class="draft-toolbar"><p id="workout-draft-status" class="field-hint" role="status">${draft?'임시저장한 내용을 복원했어요.':copied?'지난 수업을 복사했어요. 저장 전 내용을 확인해주세요.':'작성 중인 내용은 이 기기에 자동으로 임시저장됩니다.'}</p><button type="button" class="link" data-action="discard-workout-draft">초안 지우기</button></div><p class="field-hint">공개 시각: ${addDays(date,-1)} ${releaseTime} · 수업 저장을 누르면 회원에게 반영됩니다.</p><div id="workout-sections">${sections.map(editorSection).join('')}</div><button type="button" class="btn soft" data-action="add-section">${icon('plus')}구간 추가</button>${holidayState.dates[date]||['rest','open-gym'].includes(workoutDayState(date,holidayState.dates))?`<label class="field" style="margin-top:20px">${esc(holidayState.dates[date]?.name||'주말')} 특별 수업 시작 시각<input name="sessions" required value="${esc(sessionText)}" placeholder="예: 10:00, 11:00"></label><p class="field-hint">특별 수업 시작 시각을 지정해주세요. 각 수업은 1시간입니다.</p>`:''}<input type="hidden" name="overview" value="${esc(w.overviewId?'https://youtu.be/'+w.overviewId:'')}"><div class="form-footer">${w.sections.length?`<button type="button" class="btn danger-button" data-delete-workout="${date}_${p}">수업 삭제</button>`:''}<button class="btn primary">수업 저장</button></div></form>`);
 mountMovementAutocomplete($('#modal-body'),()=>libraryState.map(m=>m.name));mountSectionEditor($('#workout-form'));draftForm=$('#workout-form');draftBaseline=JSON.stringify(readWorkoutEditor(draftForm));if(copied)flushWorkoutDraft(true);
 draftForm.addEventListener('input',scheduleWorkoutDraft);draftForm.addEventListener('change',scheduleWorkoutDraft);
}

