const actions={close,settings:()=>go('settings'),today:()=>{date=today();program=null;chosenSession=null;render()},'prev-date':()=>shiftDate(-1),'next-date':()=>shiftDate(1),record:()=>recordForm(),'rm-add':()=>rmForm(),rank:()=>{state.rank=!state.rank;state.rankByMember??={};state.rankByMember[viewer.id]=state.rank;state.records.filter(isOwnRecord).forEach(r=>r.rank=state.rank);save();render();toast(state.rank?'순위 참여를 켰어요.':'순위 참여를 껐어요. 기록은 계속 공개돼요.')},notice:()=>{modal('ONOFF 공지사항',`<div class="post-body">${esc(bannerState.text)}</div><button class="btn primary full" data-action="close">확인</button>`)},'notice-toggle':()=>go('admin/banner'),'edit-notice':()=>go('admin/banner'),name:()=>toast('승인 후 이름 정정은 운영자에게 요청해주세요.'),'signup-preview':()=>modal('회원 가입 신청 · 체험',`<form id="signup-form"><label class="field">체육관에서 사용하는 실명<input name="name" required minlength="2" maxlength="20" placeholder="이름을 입력해주세요"></label><p class="field-hint">실제 개인정보 수집 없이 화면 흐름을 확인하는 예시입니다. 승인된 회원에게 이름과 운동 기록이 공개되는 구조입니다.</p>${privacyLinks()}<p class="field-hint">실제 가입 전 수집·이용 및 회원 간 기록 공개 안내와 필요한 동의 절차를 확정합니다.</p><label class="checkbox-label"><input type="checkbox" required>미리보기 가입 신청임을 확인했습니다.</label><button class="btn primary full">승인 신청 체험</button></form>`),'attendance-history':()=>go('records/attendance'),attendance:async()=>{if(!schedule(today()).length)return toast('휴강일에는 출석할 수 없어요.');if(state.attendance.includes(today()))return toast('오늘은 이미 출석했어요.');const button=document.querySelector('[data-action="attendance"]');if(button)button.disabled=true;try{await request('/api/attendance',{});await loadServer(false);toast('오늘 출석을 완료했어요.')}catch(e){toast(e.message)}finally{if(button)button.disabled=false}},'new-post':()=>modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category"><option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="80" placeholder="어떤 이야기를 나눌까요?"></label><label class="field">내용<textarea name="body" required maxlength="3000" placeholder="일시, 장소, 참여 방법 등을 적어주세요."></textarea></label><p class="field-hint">미리보기 글은 이 브라우저에만 저장됩니다.</p><button class="btn primary full">게시글 등록</button></form>`),'preview-info':showInfo};
function shiftDate(n){const target=addDays(date,n);if(!can('workouts.read')){if(!isReleased(target,serverNow()))return toast('해당 날짜 전날 '+releaseTime+'에 공개됩니다.')}const d=new Date(date+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+n);date=d.toISOString().slice(0,10);program=null;chosenSession=null;render()}
document.addEventListener('click',async e=>{let el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.memberTab){switchMemberTab(d.memberTab);return}if(d.deletePass){confirmPassDelete(d.deletePass,d.passId);return}if(d.confirmPassDelete){await deletePass(d.confirmPassDelete,d.passId,Number(d.passRevision));return}if(d.deleteRm){confirmRmDelete(d.deleteRm);return}if(d.confirmRmDelete){await deleteRm(d.confirmRmDelete);return}if(d.courseToggle){toggleCourseSection(el);return}if(d.memberApprove){approveMember(d.memberApprove);return}if(d.memberDetail){memberDetail(d.memberDetail);return}if(d.editRm){rmForm('front-squat',d.editRm);return}if(d.removeSection!==undefined){removeWorkoutSection(Number(d.removeSection));return}if(d.workoutCopy){openWorkoutCopy(d.workoutCopy);return}if(d.memberRoleFilter){memberPage=0;memberRoleFilter=d.memberRoleFilter;memberFilter='all';render();return}if(d.memberFilter){memberPage=0;memberFilter=d.memberFilter;renderMemberResults();return}if(d.deleteWorkout){confirmWorkoutDelete(d.deleteWorkout);return}if(d.confirmWorkoutDelete){await deleteWorkout(d.confirmWorkoutDelete);return}if(d.avatarEmoji){chooseAvatar(d.avatarEmoji);return}if(d.calculate){openRmCalculator(d.calculate);return}if(d.percent){calculatorPercent=+d.percent;const input=$('#calc-percent');if(input)input.value=String(calculatorPercent);updateCalculator();return}if(d.noticeEdit){noticePostForm(d.noticeEdit);return}if(d.noticeDelete){confirmNoticeDelete(d.noticeDelete);return}if(d.noticeDeleteConfirm){deleteNotice(d.noticeDeleteConfirm);return}if(d.calendarDate){chooseCalendarDate(d.calendarDate);return}if(d.calendarShift){calendarMonth=addDays(calendarMonth,+d.calendarShift<0?-1:32).slice(0,7)+'-01';showCalendar();return}if(d.roleSave){updateRole(d.roleSave);return}if(d.movement){movementModal(d.movement);return}if(d.video){videoModal(d.video,d.videoTitle||'운동 설명');return}if(d.sectionRecord){recordForm();const select=$('#record-section');if(select){select.value=String(+d.sectionRecord-1);recordFields()}return}if(d.sectionHistory){sectionHistory(+d.sectionHistory-1);return}if(d.sectionResults){resultSection='S'+d.sectionResults;recordsFilter=program;go('members');return}if(d.workoutDate){date=d.workoutDate;workoutForm(d.workoutProgram);return}if(d.page)return go(d.page);if(d.action)return actions[d.action]?.();if(d.unit){state.unit=d.unit;save();render();refreshRmCalculator();return}if(d.program){program=d.program;const track=$('.home-course-carousel'),card=track?.querySelector('[data-course="'+program+'"]');if(card){track.scrollTo({left:card.offsetLeft,behavior:'instant'});track.style.height=Math.ceil(card.getBoundingClientRect().height)+'px';document.querySelectorAll('[data-program]').forEach(b=>{b.classList.toggle('active',b.dataset.program===program);b.setAttribute('aria-pressed',String(b.dataset.program===program));});return;}return render()}if(d.session){const s=schedule(date).find(s=>s.time===d.session);chosenSession={...s,date,current:date===today()&&minutes(s.time)<=seoulNow()&&minutes(s.end)>seoulNow()};program=s.type==='B/T'?'B/T':'WOD';return render()}if(d.recordsFilter){return switchRecordProgram(d.recordsFilter)}if(d.boardFilter){boardFilter=d.boardFilter;communityPage=0;return render()}if(d.mytab){myTab=d.mytab;return render()}if(d.rm)return rmForm(d.rm);if(d.editRecord)return recordForm(d.editRecord);if(d.rmHistory)return rmHistory(d.rmHistory);if(d.post)return postModal(d.post);if(d.join){await participatePost(d.join);return;}if(d.deletePost){const p=state.posts.find(p=>p.id===d.deletePost);if(!p||((!coach||memberPreview)&&p.authorId!==viewer.id))return;modal('게시글 삭제',`<p>이 게시글과 댓글을 삭제할까요?</p><div class="form-footer"><button class="btn" data-post="${p.id}">돌아가기</button><button class="btn primary" data-confirm-delete="${p.id}">삭제하기</button></div>`);return}if(d.confirmDelete){if(shared){await sharedPostAction('/api/posts/delete',d.confirmDelete,true);return;}state.posts=state.posts.filter(p=>p.id!==d.confirmDelete);save();close(true);render();return toast('게시글을 삭제했어요.')}if(d.editWorkout)return workoutForm(d.editWorkout);if(d.approve&&coach){const m=state.members.find(m=>m.id===d.approve);m.status='approved';save();render();toast(`${m.name}님의 체험 승인을 완료했어요.`)}});
