window.addEventListener('hashchange',()=>{flushWorkoutDraft();const requested=location.hash.slice(1)||'login',p=resumePage({shared,page:requested,mode:authMode,viewer,approvalTarget});if(p!==requested)history.replaceState(null,'','#'+p);if(p!==page){if(!unsaved.allow()){history.replaceState(null,'','#'+page);return}if($('#modal').open)close(true);const previous=page;adminScroll.leave(previous,appScrollTop());page=p;render();restoreRouteScroll(previous,page)}});

function tick(){$('#live-clock').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(serverNow())+' KST'}
setTheme();render();tick();loadServer();setInterval(()=>{tick();if(!$('#modal').open&&!document.hidden&&!$('#main form'))loadServer(false)},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#modal').open&&!$('#main form'))loadServer(false)});

async function request(path,body,options={}){if(shared)return backendRequest(path,body,options);if(globalThis.ONOFF_DEMO)return demoRequest(path,body);const opts=body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{};const res=await fetch(path,{...opts,signal:options.signal});let data;try{data=await res.json()}catch{throw new Error('서버 응답을 확인할 수 없어요. 잠시 후 다시 시도해주세요.')}if(!res.ok){const e=new Error(data.error||'요청을 처리하지 못했어요.');Object.assign(e,data,{status:res.status});throw e}return data;}
// Finish asynchronous reads before applying state; stale responses must not undo a date change or logout.
async function loadServer(showLoading=true){const revision=++loadRevision,loadedAvatarRevision=avatarRevision;if(shared)await authReady;if(revision!==loadRevision)return null;const requestedDate=requestedRecordDate(),preview=memberPreview,current=()=>revision===loadRevision&&requestedDate===requestedRecordDate()&&preview===memberPreview;if(showLoading)loading=true;try{serverDataDate=requestedDate;const [data,subscription]=await Promise.all([request('/api/bootstrap'+(shared?'?date='+encodeURIComponent(requestedDate)+(preview?'&view=member':'')+(linkedPost?'&post='+encodeURIComponent(linkedPost):''):(preview?'?view=member':''))),deviceSubscription()]);if(!current())return null;if(shared){state.records=data.records||[];state.rms=data.rms||[];state.posts=data.posts||[];if(data.viewer){state.avatarByMember??={};if(!avatarPending&&loadedAvatarRevision===avatarRevision)state.avatarByMember[data.viewer.id]=avatarEmoji(data.preferences?.avatarEmoji);state.rankByMember??={};state.rankByMember[data.viewer.id]=data.preferences?.rank!==false;if(Array.isArray(data.preferences?.rmSelection)){state.rmSelections??={};state.rmSelections[data.viewer.id]=data.preferences.rmSelection;}}if(!data.viewer){viewer=null;coach=false;loading=false;apiError='';state.name='온오프 회원';state.members=[];state.workouts={};state.attendance=[];page='login';history.replaceState(null,'','#login');render();return data;}}setNamedState(data.named);privacyReviewPending=data.privacyReviewRequired===true;setPoints(data.points);bannerState=data.banner||{...DEFAULT_BANNER};pushState=data.push||pushState;devicePushEnabled=!!subscription&&(!shared||!!data.push?.subscribed);releaseTime=data.releaseTime||'22:00';publishedDates=data.publishedDates||[];notices=data.notices||[];if(data.calendar)holidayState=data.calendar;viewer=data.viewer;walletPreference=typeof data.preferences?.showMembershipWallet==='boolean'?data.preferences.showMembershipWallet:undefined;pushOnboardingPending=data.preferences?.pushOnboardingSeen===false;if(pushOnboardingPending&&devicePushEnabled){pushOnboardingPending=false;request('/api/preferences',{pushOnboardingSeen:true}).catch(()=>{});}{const savedReads=shared?data.preferences?.communityReads||{}:state.communityReadsByMember?.[viewer.id]||{};communityReads=communityReadsOwner===viewer.id?{...savedReads,...communityReads}:{...savedReads};communityReadsOwner=viewer.id;}state.avatarByMember??={};if(!avatarPending&&loadedAvatarRevision===avatarRevision)state.avatarByMember[viewer.id]=avatarEmoji(data.preferences?.avatarEmoji||state.avatarByMember[viewer.id]);selfMembership=data.membership||null;selfMembershipAccess=data.membershipState?.active??true;memberships=data.memberships||[];membershipEvents=data.membershipEvents||[];memberAttendance=data.memberAttendance||[];tvSettings=data.tv||{};rmCatalogue=data.rmCatalogue||structuredClone(DEFAULT_RM_CATALOGUE);rmCategories=data.rmCategories||structuredClone(RM_CATEGORIES);serverOffset=Date.parse(data.serverNow)-Date.now();state.attendance=data.attendance||[];state.workouts=data.workouts||{};accWorkouts=data.accWorkouts||{};videoCategories=data.videoCategories||[...VIDEO_CATEGORIES];state.members=data.members||[];recordMembers=data.recordMembers||[];photos=data.photos||[];photoOwner(viewer);authorizePhotos(photos);if(!memberFilterInitialized&&data.viewer?.status==='approved'){memberFilter=state.members.some(m=>m.status==='pending')?'pending':'approved';memberFilterInitialized=true;}libraryState=data.library||[];state.name=viewer.name;if(avatarPending||avatarRevision!==loadedAvatarRevision)applyAvatar(avatarEmoji(state.avatarByMember?.[viewer.id]));state.rank=state.rankByMember?.[viewer.id]??true;const identityChanged=synchronizeIdentity(state,viewer,state.members),movementChanged=synchronizeRmMovements(state,rmCatalogue);if(identityChanged||movementChanged)save();coach=viewer.role==='admin'&&viewer.status==='approved';const resumed=resumePage({shared,page,mode:authMode,viewer,approvalTarget});if(resumed!==page){page=resumed;history.replaceState(null,'','#'+page);}apiError='';loading=false;render();nextReleaseRefresh();maybeOpenLinkedPost();return data;}catch(e){if(!current())return null;loading=false;if(shared&&e.status===401){viewer=null;coach=false;state.records=[];state.rms=[];state.posts=[];state.workouts={};state.members=[];state.attendance=[];apiError='';page='login';history.replaceState(null,'','#login');render();return null;}if(showLoading||!viewer){apiError=e.message;render()}else toast(e.message);return null}}
function sectionCard(sec,i){const ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[];return `<div class="workout-section"><div class="section-mark">S${i+1}</div><details class="section-details" open><summary class="section-heading"><h3>${esc(sec.title)}</h3>${sec.record?`<span class="mini-badge">${esc(sec.kind)} 기록</span>`:''}</summary><div class="exercise">${workoutText(sec.text)}</div>${sectionRmReference(sec,i)}<div class="section-movement-links">${ms.map(name=>{const m=findVideoMovement(libraryState,name);return `<button class="movement-link" data-movement="${esc(name)}" aria-label="${esc(name)} 동작 설명">${m?.videoId?'▶ ':''}${esc(name)} ${m?.videoId?'영상':'↗'}</button>`}).join('')}</div></details></div>`;}
function libraryPage(){return `${backTo(can('videos')?'admin':'home',can('videos')?'운영 관리':'오늘의 운동')}${intro(can('videos')?'운동 영상 관리':'운동 영상','동작 설명과 영상을 확인해보세요.')}<div class="library-page-head"><input type="search" id="library-search" class="search-input" placeholder="동작 검색 · 예: Front Squat" aria-label="동작 검색" value="${esc(librarySearch)}">${can('videos')?'<button class="btn primary" data-action="movement-add">'+icon('plus')+'동작 등록</button>':''}</div><div class="library-classification"><label class="field library-category-field">대분류<select id="library-category"><option value="all">전체 분류</option>${videoCategories.map(([id,label])=>`<option value="${esc(id)}" ${libraryCategory===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label>${can('videos')?'<button class="btn soft" data-action="video-categories">분류 관리</button>':''}</div><div class="library-groups" id="library-cards">${libraryCards()}</div>`;}

function libraryCards(){return categoryMarkup(videoGroups(libraryState,rmCatalogue,{search:librarySearch,category:'all',categories:videoCategories}),g=>`<section class="library-group"><h2>${esc(g.label)} <span>${g.items.length}개</span></h2><div class="library-grid">${g.items.map(m=>`<article class="panel movement-card"><button type="button" class="movement-card-main" data-movement="${esc(m.name)}"><h3>${esc(m.name)}${m.videoId?'<span class="mini-badge rm-default-badge video-connected-badge">영상 연결</span>':''}</h3><p>${m.videoId?'동작 설명 영상':'동작 설명 영상 준비 중'}</p></button>${can('videos')?`<div class="movement-card-actions"><button type="button" class="icon-control" data-movement-edit="${esc(m.name)}" aria-label="${esc(m.name)} 수정">${icon('edit')}</button><button type="button" class="icon-control danger-button" data-movement-remove="${esc(m.name)}" aria-label="${esc(m.name)} 삭제">${icon('trash')}</button></div>`:''}</article>`).join('')}</div></section>`,esc)||'<div class="panel empty" role="status">검색 결과가 없어요.</div>';}
function movementModal(name){const m=findVideoMovement(libraryState,name)||{name,notes:'',videoId:''};modal(esc(m.name),`${videoFrame(m.videoId,m.name)}${m.notes?`<div class="post-body">${esc(m.notes)}</div>`:''}${can('videos')?`<div class="movement-actions"><button class="btn soft" data-movement-edit="${esc(m.name)}">영상·설명 수정</button><button class="btn danger-button icon-control" data-movement-remove="${esc(m.name)}" aria-label="동작 삭제" title="동작 삭제">${icon('trash')}</button></div>`:''}`);}
function videoModal(id,title){if(!/^[\w-]{11}$/.test(id))return;modal(esc(title),`<iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/${id}" title="${esc(title)}" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a class="btn full" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">유튜브에서 보기 ↗</a><p class="field-hint">재생되지 않으면 유튜브에서 열어주세요.</p>`);}
function movementForm(name=''){if(!can('videos'))return;const m=findVideoMovement(libraryState,name)||{name,videoId:'',notes:'',categoryId:'other'};modal(name?'운동 영상·설명 수정':'운동 동작 등록',`<form id="movement-form" data-original-name="${esc(name)}"><label class="field">동작 이름<input name="name" required maxlength="80" minlength="2" value="${esc(m.name)}" placeholder="예: Front Squat"></label><label class="field">대분류<select name="categoryId" required>${categoryOptions(m.categoryId)}</select></label><label class="field">유튜브 영상 주소 (선택)<input name="url" type="url" value="${m.videoId?'https://youtu.be/'+m.videoId:''}" placeholder="https://youtu.be/…"></label><label class="field">동작 설명·코칭 포인트<textarea name="notes" maxlength="1000">${esc(m.notes)}</textarea></label><p class="field-hint">영상 없이 동작부터 등록해도 됩니다. 관련 동작이 지정된 수업에 연결됩니다.</p><div class="form-footer">${name?`<button type="button" class="btn danger-button icon-control" data-movement-remove="${esc(m.name)}" aria-label="동작 삭제">${icon('trash')}</button>`:''}<button class="btn primary">저장</button></div></form>`);}
function sectionHistory(index){const sec=workout().sections[index];if(!sec)return;const ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[];const rows=state.records.filter(r=>isOwnRecord(r)&&(ms.length?ms.some(m=>r.movement===m||r.movements?.includes(m)):r.program===program&&r.section==='S'+(index+1)));modal('나의 운동 기록',`<p class="field-hint">${ms.length?ms.map(esc).join(' · '):esc(sec.title)}</p>${rows.length?rows.slice().reverse().map(r=>`<div class="history-row"><div>${esc(r.date)}<small>${r.program} · ${r.section}</small></div><strong>${resultValue(r)}</strong></div>`).join(''):'<div class="empty">아직 남긴 기록이 없어요.</div>'}`);}
function sectionPolicyEditor(sec,i){const p={...recordPolicy({kind:sec.kind}),...sec.recordPolicy};return `<div class="section-policy" data-section-policy="${i}"><label class="field">순위 계산<select name="ranking${i}" data-policy-ranking><option value="auto" ${p.ranking==='auto'?'selected':''} ${['세트별 횟수·칼로리','자유 기록'].includes(sec.kind)?'disabled':''}>기록 종류에 맞춰 비교</option><option value="metric" ${p.ranking==='metric'?'selected':''}>별도 숫자 하나로 비교</option><option value="none" ${p.ranking==='none'?'selected':''}>기록만 남기기 · 순위 없음</option></select></label><div data-policy-metric ${p.ranking==='metric'?'':'hidden'}><label class="field">비교할 값 이름<input name="metricLabel${i}" maxlength="40" value="${esc(p.metricLabel)}" placeholder="예: 총 횟수, 최고 중량"></label><label class="field">순위 기준<select name="metricOrder${i}"><option value="desc" ${p.metricOrder==='desc'?'selected':''}>큰 값이 높은 순위</option><option value="asc" ${p.metricOrder==='asc'?'selected':''}>작은 값이 높은 순위</option></select></label></div><label class="field" data-policy-cap ${sec.kind==='시간'?'':'hidden'}>타임캡 수행량 단위<select name="capUnit${i}">${['횟수','칼로리','라운드 + 횟수'].map(v=>`<option ${p.capUnit===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="field-hint">회원은 구간에 맞는 양식으로 입력해요. ${conditionLabel('rx')}와 Scaled는 따로 비교합니다.</p></div>`;}
document.addEventListener('change',e=>{const section=e.target.closest('.record-form-section');if(!section)return;const policy=section.querySelector('.section-policy');if(!policy)return;const kind=section.querySelector('[name^="kind"]').value,select=policy.querySelector('[data-policy-ranking]');if(e.target.name.startsWith('kind')){const complex=['세트별 횟수·칼로리','자유 기록'].includes(kind);select.querySelector('[value="auto"]').disabled=complex;if(complex&&select.value==='auto')select.value='none';}policy.querySelector('[data-policy-metric]').hidden=select.value!=='metric';policy.querySelector('[data-policy-cap]').hidden=kind!=='시간';});
function editorSection(sec,i){return `<section class="record-form-section"><div class="editor-section-heading"><h3>S${i+1}</h3><button type="button" class="btn section-remove" data-remove-section="${i}" aria-label="S${i+1} 구간 제거">− 구간 제거</button></div><input type="hidden" name="title${i}" value="${esc(sec.title||'')}"><label class="field">운동 내용<textarea name="text${i}" required maxlength="5000">${esc(sec.text||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="record${i}" ${sec.record?'checked':''}>이 구간 기록 받기</label><label class="field">기록 종류<select name="kind${i}">${KINDS.filter(k=>k!=='없음').map(k=>`<option ${sec.kind===k?'selected':''}>${k}</option>`).join('')}</select></label>${sectionPolicyEditor(sec,i)}<label class="field">관련 동작 · 선택<div class="movement-picker"><input name="movements${i}" data-movement-input role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="movement-options-${i}" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="1000" value="${esc((sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[]).join('; '))}" placeholder="검색하거나 직접 입력 · 여러 개는 쉼표로 구분"><div id="movement-options-${i}" class="movement-suggestions" role="listbox" hidden></div></div></label><p class="field-hint">동작 이름이 달라도 수업은 저장됩니다. 영상·1RM 자동 연결은 등록된 동작에만 적용됩니다.</p></section>`;}

let xlsxReady;
async function loadXlsx(){if(window.XLSX)return window.XLSX;if(!xlsxReady)xlsxReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>{xlsxReady=null;script.remove();reject(new Error('엑셀 읽기 기능을 불러오지 못했어요. 다시 시도해주세요.'))};document.head.appendChild(script)});return xlsxReady;}
async function excelFile(file){if(!file)return;if(!(can('workouts.create')||can('workouts.update')))return toast('수업 관리 권한이 필요해요.');if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('.xlsx 파일을 선택해주세요.');if(file.size>3*1024*1024)return toast('3MB 이하 파일을 선택해주세요.');modal('엑셀 파일 확인 중','<p>수업 내용과 날짜를 확인하고 있어요…</p>');try{const XLSX=await loadXlsx(),book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const sheet=book.Sheets['수업등록'];if(!sheet)throw new Error('수업등록 시트가 없어요. 제공된 양식을 사용해주세요.');const range=XLSX.utils.decode_range(sheet['!ref']||'A1');if(range.e.r>1000)throw new Error('최대 1,000행까지 등록할 수 있어요.');const head=XLSX.utils.sheet_to_json(sheet,{header:1,range:0,raw:false})[0]||[];const missing=HEADERS.slice(0,6).filter(h=>!head.includes(h));if(missing.length)throw new Error('필수 열이 없어요: '+missing.join(', '));const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false,dateNF:'yyyy-mm-dd'});const validated=normalizeRows(rows,libraryState.map(m=>m.name),holidayState.dates);if(validated.errors.length){importWorkouts=[];return modal('엑셀 내용을 확인해주세요',`<div class="import-error">${validated.errors.slice(0,40).map(esc).join('<br>')}</div><p class="field-hint">아직 저장된 내용은 없습니다. 오류를 수정한 뒤 다시 올려주세요.</p><button class="btn full" data-action="close">닫기</button>`)}if(!validated.workouts.length)throw new Error('등록할 수업이 없어요. 수업등록 시트에 내용을 작성해주세요.');importWorkouts=validated.workouts;importPreview(file.name);}catch(e){importWorkouts=[];modal('파일을 확인해주세요',`<p>${esc(e.message)}</p><button class="btn full" data-action="close">확인</button>`);}}
function importPreview(filename='선택한 파일',serverCollisions=[]){const overlaps=serverCollisions.length?serverCollisions:importWorkouts.filter(w=>state.workouts[w.date+'_'+w.program]).map(w=>w.date+' '+w.program);modal('수업 일괄 등록 미리보기',`<p><strong>${esc(filename)}</strong><br>${importWorkouts.length}개 수업 · ${importWorkouts.reduce((a,w)=>a+w.sections.length,0)}개 구간</p><div class="upload-preview"><table class="import-table"><thead><tr><th>날짜</th><th>수업</th><th>구간</th><th>공개</th></tr></thead><tbody>${importWorkouts.map(w=>`<tr><td>${w.date}</td><td>${w.program}</td><td>${w.sections.length}개</td><td>${isReleased(w.date,serverNow())?'등록 즉시 공개':addDays(w.date,-1)+' '+releaseTime}</td></tr>`).join('')}</tbody></table></div>${overlaps.length?`<div class="import-error">기존 수업과 ${overlaps.length}개가 겹쳐요.<br>${overlaps.slice(0,8).map(esc).join('<br>')}</div><label class="checkbox-label"><input type="checkbox" id="overwrite-check">기존 수업 내용을 이 파일의 내용으로 덮어씁니다.</label>`:''}<p class="field-hint">저장 전입니다. 날짜와 수업 내용을 확인해주세요. 미래 수업은 전날 ${releaseTime}에 공개됩니다.</p><div class="form-footer"><button class="btn" data-action="close">취소</button><button class="btn primary" data-action="import-save">${importWorkouts.length}개 수업 등록</button></div>`);}
async function importSave(){if(!(can('workouts.create')||can('workouts.update'))||!importWorkouts.length)return;const check=$('#overwrite-check');if(check&&!check.checked)return toast('기존 수업 덮어쓰기를 확인해주세요.');const button=$('[data-action="import-save"]');button.disabled=true;try{const result=await request('/api/workouts',{workouts:importWorkouts,overwrite:!!check?.checked});importWorkouts=[];await loadServer(false);close(true);toast(`${result.count}개 수업을 등록했어요. 전날 ${releaseTime}에 공개됩니다.`)}catch(e){if(e.status===409)return importPreview('선택한 파일',e.collisions);toast(e.errors?.[0]||e.message);button.disabled=false;}}
async function updateRole(id){if(viewer?.role!=='admin')return;const role=document.getElementById('role-'+id)?.value,status=document.getElementById('status-'+id)?.value;try{await request('/api/members',{id,role,status});await loadServer(false);toast('회원 권한을 저장했어요.')}catch(e){toast(e.message)}}
async function serverForm(f,data){if(await communitySettingsForm(f,data))return true;if(!['workout-form','movement-form','name-form','profile-pending-form'].includes(f.id))return false;const submit=f.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(f.id==='workout-form'){if(!(can('workouts.create')||can('workouts.update')))return true;const sections=readWorkoutEditor(f).sections;const overviewId=data.overview?youtubeId(data.overview):'';if(overviewId===null)throw new Error('유효한 유튜브 영상 주소를 입력해주세요.');const validated=validateWorkouts([{date,program:f.dataset.program,sections,overviewId,sessions:(data.sessions||'').split(',').map(v=>v.trim()).filter(Boolean)}],libraryState.map(m=>m.name),holidayState.dates);if(validated.errors.length)throw new Error(validated.errors[0]);await request('/api/workouts',{workouts:validated.workouts,overwrite:true});clearWorkoutDraft(f);}else if(f.id==='movement-form'){await request('/api/movements',{...data,originalName:f.dataset.originalName||undefined});}else{await request('/api/profile',{name:data.name});}await loadServer(false);close(true);toast('저장했어요.');}catch(e){toast(e.errors?.[0]||e.message);}finally{if(submit)submit.disabled=false}return true;}
Object.assign(actions,{'tomorrow':()=>{const d=addDays(today(),1);if(!coach||memberPreview){if(!isReleased(d,serverNow()))return toast('내일 운동은 '+releaseTime+'에 공개됩니다.')}date=d;program=null;chosenSession=null;go('home')},'member-preview':async()=>{if(!coach)return;memberPreview=!memberPreview;await loadServer(false);go(memberPreview?'home':'admin')},'retry':()=>loadServer(),'movement-add':()=>movementForm(),'import-save':importSave,'add-section':()=>{const f=$('#workout-form');if(!f)return;const n=+f.dataset.count;if(n>=99)return;$('#extra-sections').insertAdjacentHTML('beforeend',editorSection({},n));f.dataset.count=String(n+1);}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(el?.dataset.movementEdit)movementForm(el.dataset.movementEdit)});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){librarySearch=e.target.value;$('#library-cards').innerHTML=libraryCards();mountLibraryCategories()}});
