function nextReleaseRefresh(){clearTimeout(releaseTimer);const next=releaseAt(addDays(today(),1));const target=+serverNow()<next?next:releaseAt(addDays(today(),2));releaseTimer=setTimeout(async()=>{if(!document.hidden&&!$('#modal').open&&!$('#main form'))await loadServer(false);nextReleaseRefresh()},Math.max(1000,target-(+serverNow())+100));}

function allPosts(){return [...notices,...state.posts].filter(p=>!meetupLifecycle(p,serverNow()).expired).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||(b.created_at||b.date).localeCompare(a.created_at||a.date));}
function noticePostModal(p){const shown=modal('공지사항',`${p.pinned?'<span class="tag notice-tag">📌 공지사항</span>':''}<h2 style="margin-top:13px">${esc(p.title)}</h2><div class="board-meta"><strong>${esc(p.author)}</strong> · ${p.date}</div><div class="post-body">${esc(p.body)}</div>${photoGallery(photos.filter(x=>x.notice_id===p.id))}${can('notices')?`<div class="form-footer notice-actions"><button class="btn" data-notice-delete="${p.id}">삭제</button><button class="btn primary" data-notice-edit="${p.id}">수정·고정 설정</button></div>`:''}`);if(shown!==false)markCommunityRead(p);}
function noticePostForm(id){if(!can('notices'))return;const p=notices.find(p=>p.id===id);if(!p)return;modal('공지사항 수정',`<form id="notice-post-form" data-notice-id="${p.id}"><label class="field">제목<input name="title" required maxlength="100" value="${esc(p.title)}"></label><label class="field">내용<textarea name="body" required maxlength="5000">${esc(p.body)}</textarea></label>${photoGallery(photos.filter(x=>x.notice_id===p.id),{editable:true})}${shared?photoPicker():''}<label class="checkbox-label"><input name="pinned" type="checkbox" ${p.pinned?'checked':''}>커뮤니티 상단에 고정</label><label class="checkbox-label notice-push-option"><input name="sendPush" type="checkbox">알림을 켠 회원에게 공지 푸시 보내기</label><button class="btn primary full">공지 저장</button></form>`);}
