async function deleteNotice(id){try{await request('/api/notices',{id,action:'delete'});await loadServer(false);close(true);toast('공지를 삭제했어요.')}catch(e){toast(e.message)}}
async function communitySettingsForm(f,data){const noticeForm=f.id==='notice-post-form'||f.id==='post-form'&&data.category==='공지사항';if(!noticeForm&&f.id!=='release-time-form')return false;if(!(noticeForm?can('notices'):can('release'))){toast('관리 권한이 필요해요.');return true}const submit=f.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(noticeForm){f.dataset.noticeId||=crypto.randomUUID();await request('/api/notices',{id:f.dataset.noticeId,title:data.title,body:data.body,pinned:data.pinned==='on',sendPush:data.sendPush==='on',photoIds:await uploadPhotos(f,request,'notice')});}else await request('/api/settings',{releaseTime:data.releaseTime});await loadServer(false);close(true);toast(noticeForm?'공지를 저장했어요.':'운동 공개 시각을 '+releaseTime+'로 변경했어요.');}catch(e){toast(e.message)}finally{if(submit)submit.disabled=false}return true;}
function monthGrid(month,interactive=true){const year=+month.slice(0,4),m=+month.slice(5,7),days=new Date(year,m,0).getDate(),offset=new Date(month+'T12:00:00+09:00').getUTCDay();return `<div class="calendar holiday-calendar ${interactive?'':'attendance-calendar'}">${['일','월','화','수','목','금','토'].map((d,i)=>`<span class="weekday ${i===0?'holiday-day':''}">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=month.slice(0,8)+String(i+1).padStart(2,'0'),h=holidayState.dates[d],cls=[h?'holiday-day':'',state.attendance.includes(d)?'attended':'',d===today()?'today':'',d===date?'selected-day':''].join(' '),body=`<span class="calendar-date-number">${i+1}</span>${state.attendance.includes(d)?'<span class="attendance-emoji" role="img" aria-label="출석 완료">'+(interactive?attendanceEmoji(d,viewer?.id||''):'<span class="attendance-stamp-glyph" aria-hidden="true">'+attendanceEmoji(d,viewer?.id||'')+'</span>')+'</span>':''}${h?'<small>'+esc(h.name)+'</small>':''}`;return interactive?`<button class="${cls}" ${!(can('workouts.read')||page==='admin/acc'&&['acc.read','acc.create','acc.update','acc.delete'].some(can))?!isReleased(d,serverNow())?'disabled':'':''} data-calendar-date="${d}" aria-label="${d}${h?' '+esc(h.name):''}">${body}</button>`:`<span class="calendar-cell ${cls}" aria-label="${d}${state.attendance.includes(d)?' 출석 완료':''}">${body}</span>`}).join('')}</div>`;}
function showCalendar(){if(!calendarMonth)calendarMonth=date.slice(0,7)+'-01';modal('대한민국 공휴일 달력',`<div class="month-nav"><button class="btn" data-calendar-shift="-1" aria-label="이전 달">‹</button><strong>${calendarMonth.slice(0,4)}년 ${+calendarMonth.slice(5,7)}월</strong><button class="btn" data-calendar-shift="1" aria-label="다음 달">›</button></div>${monthGrid(calendarMonth)}<p class="field-hint">빨간 날짜는 공휴일·대체공휴일입니다. 기본 휴강이며 등록된 특별 수업이 있으면 표시됩니다.</p><p class="field-hint">${esc(holidayState.source)}${holidayState.fallback||holidayState.stale?' · 저장된 일정 사용 중':''}</p>`);}
