function pushSettings(){pushPreferences.approvals??=true;const support=pushSupport();return `<div class="push-settings"><div class="setting-row"><div><strong>웹 푸시 알림</strong><p>${devicePushEnabled?'이 기기에서 알림을 받고 있어요.':support.ok?'중요한 소식을 앱 밖에서도 받아보세요.':esc(support.reason)}</p></div><button class="btn ${devicePushEnabled?'soft':'primary'}" data-action="push-toggle" ${!devicePushEnabled&&(!support.ok||!pushState.configured)?'disabled':''}>${devicePushEnabled?'알림 끄기':'알림 켜기'}</button></div>${!pushState.configured?'<p class="field-hint">알림 서버 연결을 준비 중입니다.</p>':''}<div class="setting-row"><div><strong>운영자 공지</strong><p>운영자가 알림 보내기를 선택한 공지</p></div><button class="switch ${pushPreferences.notices?'on':''}" role="switch" aria-checked="${!!pushPreferences.notices}" aria-label="운영자 공지 알림" data-push-pref="notices"></button></div><div class="setting-row"><div><strong>내일 운동 공개 알림</strong><p>${pushState.schedulerConfigured?'설정한 공개 시각에 알려드려요.':'자동 발송 예약 연결 전 · 현재는 공지와 시험 알림 사용 가능'}</p></div><button class="switch ${pushPreferences.workouts?'on':''}" role="switch" aria-checked="${!!pushPreferences.workouts}" aria-label="운동 공개 알림" data-push-pref="workouts"></button></div>${viewer?.role==='admin'?`<div class="setting-row"><div><strong>회원 승인 요청</strong><p>새 가입 신청이 들어오면 운영자에게만 알려드려요.</p></div><button class="switch ${pushPreferences.approvals?'on':''}" role="switch" aria-checked="${!!pushPreferences.approvals}" aria-label="회원 승인 요청 알림" data-push-pref="approvals"></button></div>`:''}</div>`;}
Object.assign(actions,{'push-toggle':async()=>{const button=$('[data-action="push-toggle"]');if(button)button.disabled=true;try{if(devicePushEnabled){await disablePush(request);devicePushEnabled=false;toast('이 기기의 알림을 껐어요.')}else{await enablePush(pushState.publicKey,pushPreferences,request);devicePushEnabled=true;toast('이 기기에서 알림을 받을 수 있어요.')}render();refreshNotificationSettings();}catch(e){toast(e.message);if(button)button.disabled=false}}});
document.addEventListener('click',async e=>{const kind=e.target.closest('[data-push-pref]')?.dataset.pushPref;if(!kind)return;const previous={...pushPreferences};pushPreferences[kind]=!pushPreferences[kind];try{const sub=await deviceSubscription();if(sub)await request('/api/push/subscribe',{subscription:sub.toJSON(),preferences:pushPreferences});localStorage.setItem('onoff-push-preferences',JSON.stringify(pushPreferences));render();refreshNotificationSettings()}catch(e){pushPreferences=previous;toast(e.message)}});

function backTo(target,label){return `<button class="back-link" data-page="${target}">${icon('arrow')} ${label}</button>`;}
function folderCard(target,ic,title,description,meta){
  const tone={personCheck:'mint',calendarEdit:'blue',clipboard:'violet',play:'rose',calendar:'amber',megaphone:'amber',clock:'blue',chart:'blue',weight:'violet'}[ic]||'blue';
  const pending=target==='admin/members'&&pendingMembers()>0;
  return `<button class="panel folder-card menu-card ${pending?'needs-attention':''}" data-page="${target}"><span class="feature-icon feature-${tone}">${icon(ic)}</span><span class="folder-copy"><strong>${title}</strong><span>${description}</span><small class="${pending?'pending-label':''}">${pending?'<i></i>':''}${meta}</small></span><span class="folder-arrow">${icon('arrow')}</span></button>`;
}
function bannerMarkup(b,preview=false){
  const color=['blue','mint','amber'].includes(b.color)?b.color:'blue';
  return `<div class="notice notice-${color} ${preview?'banner-preview':''}" style="--notice-duration:${Math.max(24,Math.min(120,b.text.length*.3))}s"><span>${icon('bell')} 공지</span><div class="notice-track"><div class="notice-text"><span>${esc(b.text)}</span><span aria-hidden="true">${esc(b.text)}</span></div></div>${preview?'':`${viewer?.role==='admin'&&!memberPreview?'<button class="banner-manage" data-page="admin/banner" aria-label="홈 공지 배너 설정">설정</button>':''}<button data-action="notice" aria-label="공지 전체 내용 보기">${icon('arrow')}</button>`}</div>`;
}
function homeBanner(){return bannerState.enabled?bannerMarkup(bannerState):'';}
function updateCalculator(){
  const out=$('#calc-answer'),input=$('#calc-percent'),b=best(calculatorMovement);if(!out||!input||!b)return;
  const raw=input.value,n=Number(raw),value=percentageWeight(b.lbs,n,state.unit);
  if(raw===''||value===null){out.textContent='1~150% 사이의 비율을 입력해주세요.';return;}
  calculatorPercent=n;
  out.innerHTML=`<span>${n}% 중량</span><strong>${Number(value.toFixed(1)).toLocaleString('en-US')} <small>${state.unit}</small></strong><small>≈ ${Number(percentageWeight(b.lbs,n,state.unit==='lbs'?'kg':'lbs').toFixed(1))} ${state.unit==='lbs'?'kg':'lbs'}</small>`;
  document.querySelectorAll('[data-percent]').forEach(b=>b.classList.toggle('active',+b.dataset.percent===n));
}
