  if(section==='videos')return libraryPage();
  if(section==='calendar')return `<section class="panel settings-section"><h2>대한민국 공휴일 달력</h2><p class="field-hint">공휴일·대체공휴일은 기본 휴강입니다. 해당 날짜에 운동 내용과 시작 시각을 등록하면 특별 수업으로 표시됩니다.</p><p class="field-hint">${esc(holidayState.source)} · ${holidayState.updatedAt?holidayState.updatedAt.slice(0,10):'저장된 일정'}</p><div class="admin-actions"><button class="btn soft" data-action="calendar">공휴일 달력 보기</button>${viewer.role==='admin'?'<button class="btn" data-action="sync-holidays">일정 새로고침</button>':''}</div></section>`;
  if(section==='release')return `<section class="panel settings-section release-settings"><h2>공개 시각 설정</h2><form id="release-time-form"><div class="release-time-row"><div class="release-current"><span class="small-label">현재 공개 시각</span><strong>${releaseTime}</strong></div><label class="field">변경할 시각<input name="releaseTime" type="time" required value="${releaseTime}"></label></div><div class="release-notes"><p class="field-hint">한국 시간 · 수업 날짜 전날 설정 시각에 자동 공개됩니다.</p><p class="field-hint">아직 공개되지 않은 수업부터 적용하며, 이미 공개된 수업은 유지됩니다.</p></div><button class="btn primary full">공개 시각 저장</button></form></section>`;
  if(section==='banner')return `<section class="panel settings-section banner-editor"><h2>홈 화면 상단 공지</h2><p class="field-hint">운영자와 허용된 코치가 수정할 수 있어요. 저장한 배너는 회원의 홈 상단에 표시됩니다.</p><form id="banner-form"><label class="checkbox-label banner-enabled-label"><input name="enabled" id="banner-enabled" type="checkbox" ${bannerState.enabled?'checked':''}>홈에 공지 배너 표시</label><label class="field">공지 문구<textarea name="text" id="banner-text" required maxlength="500" rows="3">${esc(bannerState.text)}</textarea></label><p class="field-hint" id="banner-length">${bannerState.text.length} / 500자</p><fieldset class="banner-colors"><legend>배너 색상</legend>${[['blue','블루'],['mint','민트'],['amber','앰버']].map(([value,label])=>`<label class="color-choice color-${value}"><input type="radio" name="color" value="${value}" ${bannerState.color===value?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><div class="banner-preview-label">미리보기 · 저장 전</div><div id="banner-preview">${bannerMarkup(bannerState,true)}</div><button class="btn primary full">배너 설정 저장</button></form></section>`;
  if(section==='members')return approvalRequestNotice()+memberManagerPage();
