function batchContext(){
  if(!batchDate)batchDate=today();if(!batchUnit)batchUnit=state.unit;
  const w=workout(batchProgram,batchDate),sections=w.sections.map((s,i)=>({...s,key:'S'+(i+1)})).filter(s=>s.record);
  if(!sections.some(s=>s.key===batchSection))batchSection=sections[0]?.key||'';
  return{date:batchDate,program:batchProgram,section:batchSection,unit:batchUnit,sectionData:sections.find(s=>s.key===batchSection),sections};
}
function batchKey(c){return [c.date,c.program,c.section].join('|');}
function batchMembers(){return (coach?state.members:recordMembers).filter(m=>m.status==='approved').slice().sort((a,b)=>a.name.localeCompare(b.name,'ko')||a.id.localeCompare(b.id));}
function batchSearchMarkup(){
 const c=batchContext(),draft=batchDrafts.get(batchKey(c)),selected=new Set(draft?.selected||Object.keys(draft?.rows||{})),needle=batchSearch.trim().toLocaleLowerCase();
 const matches=needle?batchMembers().filter(m=>!selected.has(m.id)&&m.name.toLocaleLowerCase().includes(needle)):[];
 return needle?(matches.length?matches.slice(0,10).map(m=>`<button type="button" role="option" aria-selected="false" data-batch-add="${esc(m.id)}"><span class="avatar">${esc(avatarEmoji(m.avatarEmoji||state.avatarByMember?.[m.id]))}</span><strong>${esc(m.name)}</strong><small>${esc(m.note||'기록 입력에 추가')}</small>${icon('plus')}</button>`).join('')+(matches.length>10?'<p class="field-hint">이름을 더 입력하면 검색 범위를 줄일 수 있어요.</p>':''):'<p class="field-hint">검색된 회원이 없거나 이미 추가한 회원이에요.</p>'):'';
}
function syncBatchSearch(){const results=$('#batch-search-results'),input=$('#batch-search');if(!results||!input)return;results.innerHTML=batchSearchMarkup();results.hidden=!batchSearch.trim();input.setAttribute('aria-expanded',String(!results.hidden));}
function batchRow(m,c,draft){
 const isWeight=['중량','1RM'].includes(c.sectionData.kind),entry=draft?.rows[m.id],matches=matchingClassRecords(state.records,m,c),old=entry?.recordId?matches.find(r=>r.id===entry.recordId):findClassRecord(state.records,m,c),ambiguous=!old&&matches.length>1;
 const canonicalLbs=entry?.canonicalLbs??(isWeight?old?.lbs:undefined);let value=entry?.value??(old?isWeight&&old.lbs!=null?String(Number(fromLbs(old.lbs,c.unit).toFixed(1))):old.value||'':'');
 if(entry&&draft.unit!==c.unit&&isWeight&&value&&Number.isFinite(canonicalLbs))value=String(Number(fromLbs(canonicalLbs,c.unit).toFixed(1)));
 const note=entry?.note??old?.note??'',input=entry?.resultInput;
 const current=input?{...input,...(isWeight&&canonicalLbs!=null?{lbs:canonicalLbs}:{})}:entry?.value!==undefined&&(!entry.value||old?.result)?{}:undefined;
 return `<div class="batch-row" data-batch-member="${esc(m.id)}" data-record-id="${esc(old?.id||'')}"><div class="batch-member"><span class="avatar">${esc(avatarEmoji(m.avatarEmoji||state.avatarByMember?.[m.id]))}</span><strong>${esc(m.name)}</strong>${m.note?`<small class="member-note">${esc(m.note)}</small>`:''}${old?'<span class="mini-badge">기존 기록</span>':''}<button type="button" class="icon-control" data-batch-remove="${esc(m.id)}" aria-label="${esc(m.name)} 입력 목록에서 제거">${icon('x')}</button></div>${matches.length>1?`<label class="field batch-existing">수정할 기존 기록<select data-batch-record aria-label="${esc(m.name)} 기존 기록"><option value="">기록을 선택해주세요.</option>${matches.map(r=>`<option value="${esc(r.id)}" ${r.id===old?.id?'selected':''}>${esc(r.session||'수업 전체')} · ${r.lbs!=null?Number(fromLbs(r.lbs,c.unit).toFixed(1))+' '+c.unit:esc(r.value)}</option>`).join('')}</select></label>`:''}${recordInputMarkup(c.sectionData,{record:entry?.value!==undefined&&!entry.resultInput&&old&&!old.result?{...old,value:entry.value}:old,unit:c.unit,batch:true,disabled:ambiguous,input:current})}<label class="field batch-note"><span>메모 (선택)</span><input data-batch-note data-original-note="${esc(note)}" aria-label="${esc(m.name)} 메모" value="${esc(note)}" maxlength="150" placeholder="중량·변경 동작 등" ${ambiguous?'disabled':''}></label></div>`;
}
function batchEntryPage(){
 const c=batchContext(),members=batchMembers(),draft=batchDrafts.get(batchKey(c)),selected=draft?.selected||Object.keys(draft?.rows||{}),isWeight=['중량','1RM'].includes(c.sectionData?.kind);
 return `<section class="panel settings-section batch-panel">${!shared?'<div class="preview-note">예시 기록은 현재 브라우저에만 저장됩니다.</div>':''}<form id="batch-form" data-date="${c.date}" data-program="${c.program}" data-section="${c.section}" data-unit="${c.unit}"><div class="batch-filters"><label class="field">운동 날짜<input id="batch-date" data-unsaved-ignore type="date" value="${c.date}" max="${today()}" required></label><label class="field">수업<select id="batch-program" data-unsaved-ignore><option ${c.program==='WOD'?'selected':''}>WOD</option><option ${c.program==='B/T'?'selected':''}>B/T</option></select></label><label class="field">기록 구간<select id="batch-section" data-unsaved-ignore>${c.sections.length?c.sections.map(s=>`<option value="${s.key}" ${s.key===c.section?'selected':''}>${s.key} · ${esc(s.kind)}</option>`).join(''):'<option value="">기록 구간 없음</option>'}</select></label>${isWeight?`<label class="field">입력 단위${unitSelector(c.unit,{id:'batch-unit',attributes:'data-unsaved-ignore'})}</label>`:''}</div>${!c.sectionData?'<div class="empty">선택한 날짜·수업에 기록할 구간이 없어요.</div>':`<div class="batch-workout-summary"><span class="tag">${esc(c.section)}</span><strong>${esc(c.sectionData.title)}</strong><span>${c.sectionData.title!==c.sectionData.kind?esc(c.sectionData.kind):''}${isWeight?(c.sectionData.title!==c.sectionData.kind?' · ':'')+c.unit:''}</span></div><label class="field batch-member-search">회원 찾기<input id="batch-search" data-unsaved-ignore type="search" role="combobox" aria-autocomplete="list" aria-controls="batch-search-results" aria-expanded="${!!batchSearch.trim()}" autocomplete="off" value="${esc(batchSearch)}" placeholder="이름을 검색해 회원을 추가하세요."></label><div id="batch-search-results" class="batch-search-results" role="listbox" aria-label="회원 검색 결과" ${batchSearch.trim()?'':'hidden'}>${batchSearchMarkup()}</div><div class="batch-selected-heading"><h3>입력할 회원</h3><span>${selected.length}명</span></div><div class="batch-rows">${selected.map(id=>members.find(m=>m.id===id)).filter(Boolean).map(m=>batchRow(m,c,draft)).join('')||'<div class="empty batch-selection-empty">회원을 검색해 입력 목록에 추가해주세요.</div>'}</div><p class="field-hint">입력한 기록만 저장돼요. 빈칸은 기존 기록을 지우지 않아요.</p>${selected.length?'<label class="checkbox-label"><input id="batch-overwrite" type="checkbox">기존 기록 수정 허용</label>':''}<div id="batch-errors" role="alert" tabindex="-1"></div><div class="batch-save"><span id="batch-count" role="status"></span><button class="btn primary" id="batch-save" ${selected.length?'':'disabled'}>${icon('check')}입력한 기록 저장</button></div>`}</form></section>`;
}
function formBatchContext(f){const c={date:f.dataset.date,program:f.dataset.program,section:f.dataset.section,unit:f.dataset.unit};c.sectionData=workout(c.program,c.date).sections[Number(c.section.slice(1))-1];return c;}
function collectBatchRows(f){const members=batchMembers();return [...f.querySelectorAll('[data-batch-member]')].map(row=>{const member=members.find(m=>m.id===row.dataset.batchMember),input=readRecordInput(row);return {member,recordId:row.querySelector('[data-batch-record]')?.value||row.dataset.recordId,resultInput:input&&!('legacyValue' in input)?input:null,value:input?.legacyValue??(input?JSON.stringify(input):''),canonicalLbs:input?.lbs,note:row.querySelector('[data-batch-note]').value,rank:member?.id===viewer.id&&state.rank};});}
function rememberBatch(){const f=$('#batch-form');if(!f)return;const c=formBatchContext(f),rows=collectBatchRows(f).filter(r=>r.member),result=prepareBatchRecords({rows,context:c,records:state.records,today:today(),overwrite:true});batchDrafts.set(batchKey(c),{unit:c.unit,dirty:!!(result.errors.length||result.changes.length),selected:rows.map(r=>r.member.id),rows:Object.fromEntries(rows.map(r=>[r.member.id,{value:r.value,note:r.note,recordId:r.recordId,resultInput:r.resultInput,canonicalLbs:r.canonicalLbs}]))});}
function updateBatchCount(){const f=$('#batch-form'),out=$('#batch-count');if(!f||!out)return;for(const root of f.querySelectorAll('.structured-record'))if(!root.dataset.originalInput)mountRecordInputs(root.parentElement);const count=collectBatchRows(f).filter(r=>r.value.trim()).length;out.textContent=count+'명 입력됨';}
function batchRowDirty(row){const root=row.querySelector('.structured-record'),note=row.querySelector('[data-batch-note]');return JSON.stringify(readRecordInput(row))!==root.dataset.originalInput||note.value!==note.dataset.originalNote;}
document.addEventListener('click',e=>{
 const add=e.target.closest('[data-batch-add]'),remove=e.target.closest('[data-batch-remove]');if(!add&&!remove)return;const id=add?.dataset.batchAdd||remove.dataset.batchRemove;
 if(remove&&batchRowDirty(remove.closest('[data-batch-member]'))&&!confirm('입력 중인 이 회원의 기록을 목록에서 뺄까요?'))return;
 rememberBatch();const c=batchContext(),key=batchKey(c),draft=batchDrafts.get(key)||{unit:c.unit,selected:[],rows:{}};
 if(add&&!draft.selected.includes(id))draft.selected.push(id);if(remove){draft.selected=draft.selected.filter(x=>x!==id);delete draft.rows[id];}batchDrafts.set(key,draft);batchSearch='';render();rememberBatch();
 const row=[...document.querySelectorAll('[data-batch-member]')].find(x=>x.dataset.batchMember===id);(row?.querySelector('[data-batch-record]')||row?.querySelector('[data-result-key],[data-legacy-value]')||$('#batch-search'))?.focus();
});
document.addEventListener('change',e=>{if(!e.target.matches('[data-batch-record]'))return;const row=e.target.closest('[data-batch-member]');if(batchRowDirty(row)&&!confirm('입력 중인 값을 버리고 다른 기존 기록을 선택할까요?')){e.target.value=row.dataset.recordId;return;}rememberBatch();const c=batchContext(),draft=batchDrafts.get(batchKey(c));draft.rows[row.dataset.batchMember]={recordId:e.target.value};render();rememberBatch();});
document.addEventListener('keydown',e=>{if(e.target.id==='batch-search'){if(e.key==='ArrowDown'){$('#batch-search-results button')?.focus();e.preventDefault();}if(e.key==='Enter'){e.preventDefault();$('#batch-search-results button')?.click();}if(e.key==='Escape'){batchSearch='';e.target.value='';syncBatchSearch();}}});
async function extraForm(f,data){
  if(await gymForm(f,data))return true;

  if(f.id==='banner-form'){
    if(!can('banner')){toast('배너 관리 권한이 필요해요.');return true;}
    const finish=beginFormSubmit(f);if(!finish)return true;
    try{await request('/api/banner',{enabled:data.enabled==='on',text:data.text,color:data.color});await loadServer(false);toast('홈 공지 배너를 저장했어요.');}catch(e){toast(e.message);}finally{finish();}
    return true;
  }
  if(f.id!=='batch-form')return false;
  if(!(can('records.create')||can('records.update'))){toast('기록 관리 권한이 필요해요.');return true;}
  const c=formBatchContext(f),output=$('#batch-errors');
    const result=prepareBatchRecords({rows:collectBatchRows(f),context:c,records:state.records,today:today(),overwrite:!!$('#batch-overwrite')?.checked});
  if(result.errors.length){output.innerHTML='<ul>'+result.errors.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ul>';output.focus();return true;}
  if(!result.changes.length){toast('새로 입력하거나 변경한 기록이 없어요.');return true;}
  const oldRecords=state.records,oldRms=state.rms;
  try{
    if(shared){await request('/api/records',{records:result.changes});batchDrafts.delete(batchKey(c));await loadServer(false);toast(result.changes.length+'명의 기록을 저장했어요.');return true;}
    const ids=new Set(result.changes.map(r=>r.id));
    state.records=[...state.records.filter(r=>!ids.has(r.id)),...result.changes];
    state.rms=state.rms.filter(r=>!ids.has(r.source));
    for(const r of result.changes)if(r.kind==='1RM'&&r.memberId===viewer.id&&r.lbs&&findRmMovement(rmCatalogue,r.movement))state.rms.push({id:crypto.randomUUID(),memberId:r.memberId,source:r.id,movement:r.movement,movementId:findRmMovement(rmCatalogue,r.movement).id,lbs:r.lbs,date:r.date});
    save();batchDrafts.delete(batchKey(c));render();toast(result.changes.length+'명의 기록을 저장했어요.');
  }catch(e){state.records=oldRecords;state.rms=oldRms;output.textContent=e.message||'기록을 저장하지 못했어요. 입력 내용은 유지됩니다.';output.focus();}
  return true;
}
document.addEventListener('input',e=>{
  if(e.target.id==='calc-percent')updateCalculator();
  if(e.target.closest('[data-batch-member]')&&e.target.matches('[data-result-key],[data-legacy-value],[data-batch-note]')){rememberBatch();updateBatchCount();}
  if(e.target.id==='batch-search'){batchSearch=e.target.value;syncBatchSearch();}
  if(e.target.closest('#banner-form')){const f=$('#banner-form');$('#banner-length').textContent=f.elements.text.value.length+' / 500자';$('#banner-preview').innerHTML=bannerMarkup({text:f.elements.text.value,color:f.elements.color.value},true);}
});
document.addEventListener('change',e=>{
  if(e.target.closest('[data-batch-member]')&&e.target.matches('select[data-result-key]')){rememberBatch();updateBatchCount();return;}
  if(!['batch-date','batch-program','batch-section','batch-unit'].includes(e.target.id))return;
  rememberBatch();
  if(e.target.id==='batch-date')batchDate=e.target.value||today();
  if(e.target.id==='batch-program')batchProgram=e.target.value;
  if(e.target.id==='batch-section')batchSection=e.target.value;
  if(e.target.id==='batch-unit')batchUnit=e.target.value;
  render();
});
document.addEventListener('keydown',e=>{
  if(e.key!=='Enter'||e.isComposing||!e.target.matches('[data-batch-value],[data-batch-note]'))return;
  e.preventDefault();const rows=[...document.querySelectorAll('[data-batch-member]:not([hidden])')],index=rows.indexOf(e.target.closest('[data-batch-member]'));
  if(index<rows.length-1)rows[index+1].querySelector('[data-result-key],[data-legacy-value]')?.focus();else $('#batch-save').focus();
});

function pendingMembers(){return state.members.filter(m=>m.status==='pending').length;}
function approvalBadge(){const n=pendingMembers();return viewer?.role==='admin'&&!memberPreview&&n?`<span class="approval-count" aria-label="승인 대기 ${n}명">${n>99?'99+':n}</span>`:'';}
function memberManagerPage(){return fullMemberManager();}
function renderMemberResults(){
  if(!$('#member-results'))return;
  $('#member-results').innerHTML=memberRows();mountMemberPages();if($('#member-status-filter'))$('#member-status-filter').innerHTML=memberStatusOptions();
  document.querySelectorAll('[data-member-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.memberFilter===memberFilter);b.setAttribute('aria-pressed',String(b.dataset.memberFilter===memberFilter));});
}
async function approveMember(id){
  if(viewer?.role!=='admin'||memberPreview)return;
  const member=state.members.find(m=>m.id===id);if(!member||member.id===viewer.id||member.status!=='pending')return;
  const button=[...document.querySelectorAll('[data-member-approve]')].find(b=>b.dataset.memberApprove===id);if(button){button.disabled=true;button.setAttribute('aria-busy','true');}
  try{await request('/api/members',{id,role:'member',status:'approved'});await loadServer(false);toast(member.name+'님의 가입을 승인했어요.');}
  catch(e){toast(e.message);if(button){button.disabled=false;button.removeAttribute('aria-busy');}}
}
function batchHasUnsaved(){return [...batchDrafts.values()].some(draft=>draft.dirty===true);}

document.addEventListener('input',e=>{if(e.target.id==='member-search'){memberSearch=e.target.value;memberPage=0;renderMemberResults();}});
window.addEventListener('beforeunload',e=>{flushWorkoutDraft();if(unsaved.hasChanges()){e.preventDefault();e.returnValue='';}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();close();});

function memberRows(){return fullMemberRows();}
function memberDetail(id){return fullMemberDetail(id,'membership');}

function ownPass(){return memberships.find(p=>p.user_id===viewer?.id)||selfMembership;}
function memberPass(id){return memberships.find(p=>p.user_id===id)||(id===viewer?.id?selfMembership:null);}
function passInfoHtml(pass){const info=membershipState(pass,today(),pass?.user_id===viewer?.id&&selfMembershipAccess&&state.attendance.includes(today()));return `<div class="pass-summary"><span class="pass-status ${info.status}">${info.label}</span><strong>${membershipTitle(pass)}</strong>${pass?`<p>${pass.start_date}부터 ${pass.end_date?pass.end_date+'까지':'유효기간 제한 없음'}</p>${pass.kind==='visits'?`<p><b>${pass.remaining_visits}회 남음</b> · 하루 여러 수업에 참여해도 1회 차감</p>`:info.days>0?`<p>${info.days}일 남음</p>`:''}${pass.paused_at?`<p>${pass.paused_at}부터 휴회 중</p>`:''}`:'<p>운영자가 회원권을 등록하면 기간과 잔여횟수가 표시돼요.</p>'}</div>`;}
function themeChoices(){return `<div class="theme-options">${THEMES.map(t=>`<button class="theme-choice" data-app-theme="${t.id}" aria-pressed="${document.documentElement.dataset.theme===t.id}"><span class="theme-swatch" style="--swatch-bg:${t.background};--swatch-accent:${t.accent}">ONOFF</span>${t.name}</button>`).join('')}</div>`;}
function membershipWalletVisible(){return showMembershipWallet(viewer,{showMembershipWallet:shared?walletPreference:state.walletVisibilityByMember?.[viewer?.id]});}
function accountSettings(){const visible=membershipWalletVisible();const role=viewer?.role==='admin'?'운영자':viewer?.role==='coach'?'코치':'회원',status=viewer?.status==='approved'?'승인 완료':viewer?.status==='pending'?'승인 대기':'이용 중지';return `<div class="settings-intro">${intro('개인설정',visible?'회원권과 앱 설정을 관리해요.':'앱 설정을 관리해요.',`<div class="settings-identity"><button type="button" class="avatar settings-avatar" data-action="avatar-picker" aria-label="개인 이모지 변경">${esc(avatarEmoji(state.avatarByMember?.[viewer?.id]))}</button><span title="${esc(state.name)}">${esc(state.name)}</span></div>`)}</div><div class="settings-stack personal-settings">${visible?couponDeck(membershipCard(ownPass(),{today:today(),name:state.name,attendedToday:selfMembershipAccess&&state.attendance.includes(today())})):''}<section class="panel compact-settings"><h2>앱 설정</h2>${canToggleMembershipWallet(viewer)?`<div class="setting-row"><strong>회원카드·쿠폰</strong><button type="button" class="switch ${visible?'on':''}" role="switch" aria-checked="${visible}" aria-label="회원카드·쿠폰 표시" data-action="toggle-wallet"></button></div>`:''}<div class="setting-row"><strong>테마</strong><button class="link" data-action="theme-picker">${esc(THEMES.find(t=>t.id===savedTheme())?.name||'네이비 블루')} ${icon('arrow')}</button></div><div class="setting-row"><strong>중량 단위</strong>${unitToggle()}</div><div class="setting-row"><strong>순위 참여</strong><button class="switch ${state.rank?'on':''}" role="switch" aria-checked="${state.rank}" aria-label="순위 참여" data-action="rank"></button></div><div class="setting-row"><strong>알림</strong><button class="link" data-action="notification-settings">${devicePushEnabled?'켜짐':'꺼짐'} ${icon('arrow')}</button></div>${christmasSettingMarkup(serverNow())}</section><section class="panel settings-account"><h2>계정 관리</h2><div class="account-info">${viewer?.email?`<p>${esc(viewer.email)}</p>`:''}<p>${role} · ${status}</p></div><button class="btn soft full" data-action="password-reset">비밀번호 재설정</button><button class="btn full" data-action="logout">로그아웃</button></section><section class="panel privacy-settings-panel"><h2>개인정보 설정</h2><button class="btn soft" data-action="privacy-settings">동의 내용 확인·변경</button></section><button class="link withdrawal-link settings-withdrawal" data-action="withdrawal">회원 탈퇴</button></div>`;}
Object.assign(actions,{'toggle-wallet':async()=>{if(!canToggleMembershipWallet(viewer))return;const visible=!membershipWalletVisible(),button=$('[data-action="toggle-wallet"]');if(button?.disabled)return;if(button)button.disabled=true;try{if(shared){await request('/api/preferences',{showMembershipWallet:visible});await loadServer(false);}else{state.walletVisibilityByMember??={};state.walletVisibilityByMember[viewer.id]=visible;save();render();}toast(visible?'회원카드·쿠폰을 켰어요.':'회원카드·쿠폰을 숨겼어요.');}catch(e){toast(e.message);}finally{if(button)button.disabled=false;}}});
function showAvatarPicker(){modal('나의 이모지',`<p class="field-hint">기록과 회원 목록에 표시할 이모지를 선택하세요.</p><div id="avatar-pager">${pagerMarkup(chunks(AVATAR_EMOJIS,10).map(items=>`<div class="avatar-options">${items.map(emoji=>`<button type="button" data-avatar-emoji="${emoji}" aria-label="${emoji} 선택" aria-pressed="${avatarEmoji(state.avatarByMember?.[viewer.id])===emoji}">${emoji}</button>`).join('')}</div>`),'이모지')}</div><p id="avatar-save-status" class="field-hint" role="status"></p>`);mountAvatarPages();}
function showNotificationSettings(){modal('알림 설정',`<div data-notification-settings>${pushSettings()}</div>`);}
function refreshNotificationSettings(){const root=$('[data-notification-settings]');if(root)root.innerHTML=pushSettings();}

function passAllowsToday(){return staff()||selfMembershipAccess;}

function passBlockedView(){const p=ownPass();return `${intro('회원권을 확인해주세요.','운영자에게 연장 또는 휴회 상태를 확인해주세요.')}<section class="panel settings-section">${passInfoHtml(p)}<p class="field-hint">지난 나의 운동 기록과 1RM은 계속 확인할 수 있어요.</p><button class="btn primary" data-page="records">나의 기록 보기</button></section>`;}
function passFilterMatches(member,filter){if(memberRoleFilter!=='all'&&member.role!==memberRoleFilter)return false;if(filter==='all')return true;if(['pending','suspended'].includes(filter))return member.status===filter;if(member.status!=='approved')return false;const info=membershipState(memberPass(member.id),today());return filter==='approved'?['active','unregistered','scheduled'].includes(info.status):filter==='soon'?info.soon:info.status===filter;}
function fullMemberManager(){return `<section class="panel settings-section member-manager"><div class="member-heading"><div><h2>회원관리</h2><p class="field-hint">회원권과 승인 상태를 관리해요.</p></div>${pendingMembers()?`<button class="pending-pill" data-action="pending-members">승인 대기 ${pendingMembers()}명 →</button>`:'<span class="complete-pill">모든 회원 승인 완료</span>'}</div><div class="filter-tabs member-role-tabs" role="group" aria-label="회원 권한 구분">${[['all','전체'],['admin','운영자'],['coach','코치'],['member','회원']].map(([value,label])=>`<button data-member-role-filter="${value}" aria-pressed="${memberRoleFilter===value}" class="${memberRoleFilter===value?'active':''}">${label} <span>${state.members.filter(m=>value==='all'||m.role===value).length}</span></button>`).join('')}</div><p class="field-hint member-retention-summary">미승인·거절 계정은 30일 이내 정리해주세요.${overdueMembers()?` <strong>기한 도달 ${overdueMembers()}명</strong>`:''}</p><label class="field member-search-label">회원 이름·구분 메모 검색<input type="search" id="member-search" class="search-input" value="${esc(memberSearch)}" placeholder="이름이나 운영자용 구분 메모로 찾기"></label><label class="field member-status-select">회원 상태<select id="member-status-filter">${memberStatusOptions()}</select></label><div id="member-results">${fullMemberRows()}</div></section>`;}
function fullMemberRows(){const search=memberSearch.trim().toLowerCase(),rows=state.members.filter(m=>passFilterMatches(m,memberFilter)&&(m.name+' '+(m.note||'')).toLowerCase().includes(search)).sort(memberOrder);if(!rows.length)return `<div class="empty member-empty">${icon('personCheck')}<strong>${search?'검색된 회원이 없어요.':'해당 상태의 회원이 없어요.'}</strong>${memberFilter==='pending'?'<p>가입 신청이 들어오면 여기에 표시돼요.</p><button class="btn soft" data-member-filter="approved">이용 중인 회원 보기</button>':''}</div>`;return `<p class="member-result-count sr-only" role="status">${rows.length}명의 회원</p><div class="member-pages">${pagerMarkup(chunks(rows,10).map(group=>group.map(m=>{const p=memberPass(m.id),info=membershipState(p,today());return `<div class="member-row"><div class="member-identity"><span class="avatar ${m.status==='approved'&&p&&info.status==='active'?'member-active':m.status==='approved'&&info.status==='paused'?'member-paused':''}" aria-label="${esc(info.label)}">${esc(avatarEmoji(m.avatarEmoji||state.avatarByMember?.[m.id]))}</span><div class="member-compact-identity"><strong title="${esc(m.name+(m.note?' · '+m.note:''))}" aria-label="${esc(m.name)}${m.id===viewer.id?' · 내 계정':''}">${esc(m.name)}</strong><span class="member-role-badge ${m.role==='admin'?'is-admin':m.role==='coach'?'is-coach':'is-member'}">${m.role==='admin'?'운영자':m.role==='coach'?'코치':'회원'}</span><time class="member-expiry" ${p?.end_date?`datetime="${esc(p.end_date)}"`:''}>${p?.end_date?esc(p.end_date.replaceAll('-','.')):'—'}</time></div></div><div class="member-row-actions">${m.status==='pending'?`<button class="btn primary" data-member-approve="${esc(m.id)}">${icon('check')}승인</button>`:''}<button class="icon-control member-detail-eye" data-member-detail="${esc(m.id)}" aria-label="${esc(m.name)} 회원권·상세" title="회원권·상세">${icon('eye')}</button></div></div>`}).join('')),'회원')}</div>`;}
function memberEventActor(event,body){const name=body.actorName||state.members.find(m=>m.id===body.actor)?.name,label=event.action==='signup-approve'?'승인자':'처리자';return name?label+': '+name:label+' 정보 없음';}
function fullMemberDetail(id,tab){if(viewer?.role!=='admin'||memberPreview)return;const m=state.members.find(m=>m.id===id);if(!m)return;if(id!==memberDetailId)memberDetailTab='membership';memberDetailId=id;if(tab)memberDetailTab=tab;const p=memberPass(id),history=membershipEvents.filter(e=>e.user_id===id).slice(0,30);
 modal('회원 관리',`<div class="member-detail-summary"><span class="avatar">${esc(avatarEmoji(m.avatarEmoji||state.avatarByMember?.[id]))}</span><div><h3>${esc(m.name)}</h3><span>${m.role==='admin'?'운영자':m.role==='coach'?'코치':'회원'} · ${m.status==='approved'?'승인 완료':m.status==='pending'?'승인 대기':'이용 중지'}</span><span class="member-point-balance">보유 포인트 <strong>${Number(m.pointBalance||0).toLocaleString('ko-KR')}P</strong></span></div></div><div class="member-detail-tabs" role="tablist" aria-label="회원 관리">${[['membership','회원권'],['profile','회원 정보'],['history','관리 이력']].map(([key,title])=>`<button type="button" role="tab" id="member-tab-${key}" aria-controls="member-panel-${key}" aria-selected="${memberDetailTab===key}" data-member-tab="${key}">${title}</button>`).join('')}</div><div id="member-panel-membership" role="tabpanel" aria-labelledby="member-tab-membership" data-member-panel="membership" ${memberDetailTab!=='membership'?'hidden':''}><div class="member-pass-heading"><h3>회원권</h3>${p?`<button class="icon-action danger-link" data-delete-pass="${esc(id)}" data-pass-id="${esc(p.id)}" aria-label="회원권 삭제">${icon('close')}</button>`:''}</div>${membershipCard(p,{today:today(),name:m.name})}${p?`<div class="membership-buttons"><button class="btn soft full" data-pass-action="${p.paused_at?'resume':'pause'}" data-member-id="${esc(id)}">${p.paused_at?'운동 재개':'휴회 시작'}</button></div>`:''}<section class="membership-section"><h3>회원권 등록·연장</h3><form id="membership-form" data-member-id="${esc(id)}"><label class="field">작업<select name="action" id="pass-action"><option value="register">새 회원권 등록</option>${p?`<option value="extend" ${!p.paused_at?'selected':''}>현재 회원권 연장</option>`:''}</select></label><div class="field-row"><label class="field">회원권 종류<select name="kind" id="pass-kind"><option value="period" ${p?.kind==='period'?'selected':''}>기간권</option><option value="visits" ${p?.kind==='visits'?'selected':''}>횟수권</option></select></label><label class="field" data-pass-period>기간<select name="months" id="pass-months">${[1,3,6,12].map(n=>`<option value="${n}" ${p?.months===n?'selected':''}>${n===12?'1년':n+'개월'}</option>`).join('')}</select></label><label class="field" data-pass-visits>추가 횟수<input name="visits" type="number" min="1" max="9999" value="10"></label></div><div class="field-row"><label class="field">시작일<input name="startDate" id="pass-start" type="date" required value="${today()}"></label><label class="field">종료일 · 횟수권은 선택<input name="endDate" id="pass-end" type="date"></label></div><div class="membership-preview" id="pass-preview"></div><p class="field-hint">현재 회원권 연장은 같은 종류로 처리됩니다. 새 회원권 등록을 선택하면 이전 회원권을 대체하며 이력은 유지됩니다.</p><button class="btn primary full">회원권 저장</button></form></section>${p?`<section class="membership-section"><h3>기간·잔여 횟수 수정</h3><form id="membership-adjust-form" data-member-id="${esc(id)}"><label class="field">종료일<input type="date" name="endDate" value="${p.end_date||''}" ${p.kind==='period'?'required':''}></label>${p.kind==='visits'?`<label class="field">잔여횟수<input type="number" name="remaining" min="0" max="9999" value="${p.remaining_visits}" required></label>`:''}<label class="field">수정 사유<input name="reason" required maxlength="200" placeholder="수정 내역에 남길 사유"></label><button class="btn primary full">수정 저장</button></form></section>`:''}</div><div id="member-panel-profile" role="tabpanel" aria-labelledby="member-tab-profile" data-member-panel="profile" ${memberDetailTab!=='profile'?'hidden':''}><section class="membership-section"><h3>실명 정정</h3><form id="member-name-form" data-member-id="${esc(id)}"><label class="field">회원 실명<input name="name" minlength="2" maxlength="30" required value="${esc(m.name)}"></label><p class="field-hint">회원 고유 ID는 유지됩니다. 출석·회원권·운동기록을 다른 사람에게 이전하지 않습니다.</p><button class="btn soft">실명 정정 저장</button></form></section>${memberRolePanel(m)}<section class="membership-section"><h3>운영자용 구분 메모</h3><form id="member-note-form" data-member-id="${esc(id)}"><label class="field">동명이인 구분 등 · 회원에게는 공개되지 않습니다<textarea name="note" maxlength="500" rows="2" placeholder="예: 주로 오전 방문">${esc(m.note||'')}</textarea></label><button class="btn soft">메모 저장</button></form></section></div><div id="member-panel-history" role="tabpanel" aria-labelledby="member-tab-history" data-member-panel="history" ${memberDetailTab!=='history'?'hidden':''}><section class="membership-section"><h3>변경 이력 · ${history.length}건</h3>${m.approved_at&&!history.some(e=>e.action==='signup-approve')?'<p class="field-hint">가입 승인자 정보 없음</p>':''}<div class="membership-history">${history.map(e=>{let body={};try{body=JSON.parse(e.body)}catch{}return `<div class="membership-event-row"><div><strong>${({register:'회원권 등록',extend:'회원권 연장',pause:'휴회 시작',resume:'운동 재개',adjust:'직접 수정',delete:'회원권 삭제','attendance-cancel':'출석 취소','signup-approve':'가입 승인'})[e.action]||esc(e.action)}</strong><small>${esc(memberEventTime(e.created_at))}</small><small>${esc(memberEventActor(e,body))}</small>${body.reason?`<p>${esc(body.reason)}</p>`:''}</div><button type="button" class="icon-control danger-button" data-membership-event-delete="${esc(e.id)}" data-member-id="${esc(id)}" aria-label="관리 이력 삭제">${icon('trash')}</button></div>`}).join('')||'<p class="field-hint">아직 변경 이력이 없어요.</p>'}</div></section><section class="membership-section"><h3>출석 취소·횟수 복구</h3><form id="attendance-cancel-form" data-member-id="${esc(id)}"><label class="field">취소할 출석 날짜<input type="date" name="date" max="${today()}" value="${today()}" required></label><label class="field">취소 사유<input name="reason" required maxlength="200"></label><button class="btn soft full">출석 취소</button></form></section></div>`);updatePassPreview(true);queueMicrotask(()=>unsaved.track($('#modal-body')));}
function switchMemberTab(tab){memberDetailTab=tab;document.querySelectorAll('[data-member-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.memberTab===tab)));document.querySelectorAll('[data-member-panel]').forEach(panel=>panel.hidden=panel.dataset.memberPanel!==tab);$('.modal-content').scrollTop=0;appViewport.refresh();}

function updatePassPreview(reset=false){const f=$('#membership-form');if(!f)return;const p=memberPass(f.dataset.memberId),kind=f.elements.kind.value,action=f.elements.action.value;f.querySelectorAll('[data-pass-period]').forEach(e=>e.hidden=kind!=='period');f.querySelectorAll('[data-pass-visits]').forEach(e=>e.hidden=kind!=='visits');if(reset){if(kind==='period'){const base=action==='extend'&&p?.end_date>=today()?addDays(p.end_date,1):f.elements.startDate.value;try{f.elements.endDate.value=periodEnd(base,+f.elements.months.value)}catch{}}else f.elements.endDate.value=action==='extend'?p?.end_date||'':'';}$('#pass-preview').textContent=kind==='period'?'종료일: '+(f.elements.endDate.value||'날짜를 선택해주세요.'):'입력한 '+f.elements.visits.value+'회 '+(action==='extend'?'추가 · ':'등록 · ')+(f.elements.endDate.value?f.elements.endDate.value+'까지':'유효기간 제한 없음');}
async function gymForm(f,data){
  const paths={'membership-form':'/api/membership','membership-adjust-form':'/api/membership','member-note-form':'/api/member-note','member-name-form':'/api/member-name','member-role-form':'/api/members','attendance-cancel-form':'/api/attendance/cancel','tv-admin-form':'/api/tv/admin'};const path=paths[f.id];if(!path)return false;if(f.closest('#modal')&&unsaved.dirtyExcept(f,$('#modal-body'))&&!confirm('다른 항목에 저장하지 않은 내용이 있어요. 해당 내용은 버리고 이 항목만 저장할까요?'))return true;
  if(!(f.id==='tv-admin-form'?can('tv'):viewer?.role==='admin'&&!memberPreview)){toast('운영자 권한이 필요해요.');return true;}
  const payload={...data,id:f.dataset.memberId};if(f.id==='member-role-form')payload.coach_permissions=new FormData(f).getAll('coach_permissions');if(f.id==='membership-adjust-form')payload.action='adjust';if(f.id==='tv-admin-form'){payload.revoke=data.revoke==='on';payload.password=String(data.pin??data.password??'').trim();delete payload.pin;if(payload.password&&!/^\d{4}$/.test(payload.password)){toast('TV 암호는 숫자 4자리로 입력해주세요.');return true;}}
  const finish=beginFormSubmit(f);if(!finish)return true;try{const result=await request(path,payload);if(f.id==='tv-admin-form'&&payload.password&&!globalThis.ONOFF_DEMO&&!result.configured)throw Error('TV 암호 저장을 확인하지 못했어요. 다시 저장해주세요.');unsaved.track(f);await loadServer(false);if(f.id==='tv-admin-form'&&$('#tv-save-status'))$('#tv-save-status').textContent='TV 설정을 저장했어요. 설정한 4자리 암호로 TV에 접속해주세요.';close(true);if(f.dataset.memberId)fullMemberDetail(f.dataset.memberId);toast('저장했어요.');}catch(e){toast(e.message);if(f.id==='tv-admin-form'&&$('#tv-save-status'))$('#tv-save-status').textContent=e.message;}finally{finish();}return true;
}
async function passAction(id,action){if(viewer?.role!=='admin'||memberPreview||!unsaved.allow($('#modal-body'),false))return;const p=memberPass(id);if(action==='resume'&&!confirm(`휴회 ${memberDays(p.paused_at,today())}일을 반영해 운동을 재개할까요?`))return;try{await request('/api/membership',{id,action});await loadServer(false);close(true);fullMemberDetail(id);toast(action==='pause'?'휴회를 시작했어요.':'운동을 재개했어요.');}catch(e){toast(e.message)}}
function tvAdminPage(){const prefs=normalizeTvPreferences(tvSettings.preferences||{}),url=new URL('tv.html'+(globalThis.ONOFF_DEMO?'?preview=1':''),location.href.split('#')[0]).href;return `<section class="panel settings-section narrow-panel tv-settings-panel"><h2>TV 전용 화면</h2><p class="field-hint">B/T와 WOD를 나란히 표시하고, 수요일은 WOD만 표시합니다. 한국 시간 ${releaseTime}부터 다음 날 운동으로 자동 전환합니다.<br>TV 배경은 차콜, 원본 로고·날짜·시간은 화이트로 고정됩니다.</p><div id="tv-connection-status">${tvConnectionStatus()}</div><div class="tv-admin-preview"><span id="tv-bt-preview" style="background:${TV_COLORS.find(c=>c.id===prefs.btColor).color};color:#111820">B/T</span><span id="tv-wod-preview" style="background:${TV_COLORS.find(c=>c.id===prefs.wodColor).color};color:#111820">WOD</span></div><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener">TV 화면 열기 ↗</a><p class="field-hint">앱 등록 안내는 TV 화면의 설정 → 앱 등록 버튼에서 열 수 있어요.</p><p class="tv-url">${esc(url)}</p>${globalThis.ONOFF_DEMO?'<p class="field-hint">공개 테스트 · 최초 테스트 암호: 0000<br>이 브라우저의 예시 데이터와 설정으로 확인할 수 있어요.</p>':`<p class="field-hint">${shared?'TV 전용 암호로 접속하면 저장한 수업과 색상 설정을 함께 사용합니다.':'TV 암호로 접속합니다. 실제 TV 공유 연결은 공개 서버 연동 후 사용할 수 있습니다.'}</p>`}<form id="tv-admin-form" class="tv-settings-form"><label class="field">TV 화면 방향<select name="orientation"><option value="landscape" ${prefs.orientation==='landscape'?'selected':''}>가로 · 기본</option><option value="portrait" ${prefs.orientation==='portrait'?'selected':''}>세로</option></select></label><p class="field-hint">브라우저 화면 크기와 관계없이 선택한 구성을 유지합니다.</p><div class="field-row"><label class="field">B/T 색상<select name="btColor" id="tv-bt-color">${TV_COLORS.map(c=>`<option value="${c.id}" ${prefs.btColor===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="field">WOD 색상<select name="wodColor" id="tv-wod-color">${TV_COLORS.map(c=>`<option value="${c.id}" ${prefs.wodColor===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label></div><div class="field-row"><label class="field">중량 단위${unitSelector(prefs.unit,{name:'unit'})}</label><label class="field">페이지 전환 주기<select name="pageSeconds">${[15,20,30,45].map(n=>`<option value="${n}" ${prefs.pageSeconds===n?'selected':''}>${n}초</option>`).join('')}</select></label></div><section class="tv-auth-settings"><h3>TV 접속 관리</h3><label class="field">${tvSettings.needsPinUpdate?'TV 암호를 숫자 4자리로 다시 설정해주세요':tvSettings.configured?'새 TV 암호 (변경할 때만 입력)':'TV 암호 설정'}<input id="tv-pin" type="text" name="pin" minlength="4" maxlength="4" pattern="[0-9]{4}" inputmode="numeric" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="숫자 4자리" ${tvSettings.needsPinUpdate||!globalThis.ONOFF_DEMO&&!tvSettings.configured?'required':''}></label><p class="field-hint">암호를 변경하면 연결된 TV는 다시 접속해야 합니다. TV에서 따로 선택한 색상은 해당 TV에 유지됩니다.</p><label class="checkbox-label"><input type="checkbox" name="revoke">연결된 모든 TV 접속 해제</label></section><p id="tv-save-status" class="field-hint" role="status" aria-live="polite"></p><button class="btn primary full" type="submit">TV 설정 저장</button></form></section>`;}
function recordMemberOptions(existing){const approved=batchMembers(),selected=existing?.memberId||(existing?'':viewer.id);return `<option value="">회원을 선택해주세요.</option>${approved.map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''}>${esc(m.name)}${m.note?' · '+esc(m.note):''}</option>`).join('')}`;}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.appTheme){if(!unsaved.allow())return;applyTheme(d.appTheme);close(true);render();}if(d.passAction)passAction(d.memberId,d.passAction);});
document.addEventListener('change',e=>{if(['pass-action','pass-kind','pass-months','pass-start'].includes(e.target.id))updatePassPreview(true);if(e.target.id==='pass-end')updatePassPreview(false);});
document.addEventListener('input',e=>{if(e.target.closest('#membership-form'))updatePassPreview(false);});

$('#modal').addEventListener('close',()=>{if(!$('#modal').open){document.documentElement.classList.remove('has-modal');appViewport.modalClosed();}});

document.addEventListener('change',e=>{if(['tv-bt-color','tv-wod-color'].includes(e.target.id)){const c=TV_COLORS.find(c=>c.id===e.target.value);const preview=document.getElementById(e.target.id==='tv-bt-color'?'tv-bt-preview':'tv-wod-preview');if(c&&preview)preview.style.background=c.color;}});

Object.assign(actions,{
 'privacy-policy':()=>showPrivacy('policy'),
 'privacy-rights':()=>showPrivacy('rights'),
 'withdrawal':()=>withdrawalForm(),
 'scroll-top':()=>{scrollAppTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('.app-header a')?.focus({preventScroll:true});}
});
function showPrivacy(kind){const doc=privacyDocument(kind);modal(doc.title,doc.html);}
function updateScrollTop(){const b=$('#scroll-top');if(b)b.hidden=appScrollTop()<500||page==='login';}
window.addEventListener('scroll',updateScrollTop,{passive:true});$('.app').addEventListener('scroll',updateScrollTop,{passive:true});
window.addEventListener('hashchange',()=>requestAnimationFrame(updateScrollTop));
function updateHeaderOffset(){document.documentElement.style.setProperty('--app-header-height',($('.app-header')?.getBoundingClientRect().height||0)+'px');}
if('ResizeObserver' in window)new ResizeObserver(updateHeaderOffset).observe($('.app-header'));else window.addEventListener('resize',updateHeaderOffset);
updateHeaderOffset();

function isOwnRecord(r){return belongsTo(r,viewer?.id);}
function ownRms(){return state.rms.filter(isOwnRecord);}
function postParticipants(p){return [...(p.viewerJoined===true&&!(p.joinedIds||[]).includes(viewer?.id)?[state.name]:[]),...(p.joined||[]),...(p.joinedIds||[]).map(id=>state.members.find(m=>m.id===id)?.name||(id===viewer?.id?state.name:p.joinedNames?.[id]||'회원'))];}
function legacyIdentityNotice(){const n=[...state.records,...state.rms].filter(r=>!r.memberId).length;if(!n)return '';return `<div class="membership-warning">이전 기록 ${n}건은 회원 연결 확인이 필요합니다. 원본은 보관되며 이름만으로 다른 계정에 자동 연결하지 않습니다.${coach&&!memberPreview?'<br><button class="link" data-action="legacy-records">운영자 확인 후 연결 →</button>':'<br>운영자에게 기록 연결 확인을 요청해주세요.'}</div>`;}
function showLegacyRecords(){if(!coach||memberPreview)return;const rows=[...state.records.filter(r=>!r.memberId).map(r=>({r,kind:'record'})),...state.rms.filter(r=>!r.memberId).map(r=>({r,kind:'rm'}))];modal('이전 기록 회원 연결',`<p class="field-hint">같은 이름이어도 다른 사람일 수 있습니다. 기록의 주인을 확인한 뒤 한 건씩 연결해주세요.</p><form id="identity-link-form"><label class="field">확인할 이전 기록<select name="record" required>${rows.map(({r,kind})=>`<option value="${esc(kind+':'+r.id)}">${esc(r.date)} · ${esc(r.name||'이름 미확인')} · ${esc(r.movement||r.program||'1RM')} · ${r.lbs!=null?formatWeight(r.lbs)+' '+state.unit:esc(r.value||'')}</option>`).join('')}</select></label><label class="field">확인한 회원<select name="memberId" required>${recordMemberOptions({})}</select></label><label class="checkbox-label"><input type="checkbox" name="confirmed" required>이 기록의 회원을 확인했습니다.</label><button class="btn primary full" ${rows.length?'':'disabled'}>확인한 회원에 연결</button></form>`);}
Object.assign(actions,{'legacy-records':showLegacyRecords});

function tvConnectionStatus(){const online=(tvSettings.devices||[]).some(d=>d.online);return `<section class="tv-connection-panel"><div class="tv-connection-heading"><h3>TV 연결 상태</h3><button class="link" data-action="tv-status-refresh">새로고침</button></div><div class="tv-single-status ${online?'tv-online':'tv-offline'}">${online?'● 연결됨':'○ 연결 확인 필요'}</div></section>`;}
let tvStatusLoading=false;
async function refreshTvConnection(silent=false){if(page!=='admin/tv'||!can('tv')||tvStatusLoading)return;tvStatusLoading=true;try{tvSettings=await request('/api/tv/status');const root=$('#tv-connection-status');if(root)root.innerHTML=tvConnectionStatus();if(!silent)toast('TV 연결 상태를 확인했어요.');}catch(e){if(!silent)toast(e.message);}finally{tvStatusLoading=false}}
Object.assign(actions,{'tv-status-refresh':()=>refreshTvConnection()});
setInterval(()=>{if(!document.hidden)refreshTvConnection(true)},30000);

const sectionRmChoices=new Map();
function legacyRmMovements(){const seen=new Set();return ownRms().filter(r=>!findRmMovement(rmCatalogue,r.movementId||r.movement)&&r.movement&&!seen.has(r.movement)&&seen.add(r.movement)).map(r=>({id:'legacy:'+r.movement,name:r.movement,category:'complex',active:false,aliases:[]}));}
function allRmMovements(){return [...rmCatalogue,...legacyRmMovements()];}
function rmMovement(value){return findRmMovement(allRmMovements(),value);}
function sameRmMovement(r,value){const m=rmMovement(value),other=rmMovement(r.movementId||r.movement);return !!m&&m.id===other?.id;}
function myRmMovements(){const all=allRmMovements(),picked=state.rmSelections?.[viewer?.id];const ids=Array.isArray(picked)?picked:[...rmCatalogue.filter(m=>m.active&&m.isDefault).map(m=>m.id),...ownRms().map(r=>rmMovement(r.movementId||r.movement)?.id).filter(Boolean)];return [...new Set(ids)].map(id=>all.find(m=>m.id===id)).filter(m=>m&&(m.active||ownRms().some(r=>sameRmMovement(r,m.id))));}
function showRmPicker(){rmPickerSearch='';const selected=new Set(myRmMovements().map(m=>m.id)),items=allRmMovements().filter(m=>m.active||ownRms().some(r=>sameRmMovement(r,m.id)));modal('내 1RM 종목 추가·관리',`<p class="field-hint">내 화면에 표시할 종목을 선택하세요. 숨겨도 기존 기록은 삭제되지 않습니다.</p><label class="field">종목 검색<input type="search" id="rm-picker-search" placeholder="예: Clean, Squat"></label><form id="rm-selection-form">${rmCategories.map(([id,label])=>`<fieldset class="rm-picker-group"><legend>${label}</legend>${items.filter(m=>m.category===id).sort(movementOrder).map(m=>`<label class="rm-picker-row" data-rm-select-name="${esc(m.name.toLowerCase())}"><input type="checkbox" name="rmSelection" value="${esc(m.id)}" ${selected.has(m.id)?'checked':''}><span>${esc(m.name)}${!m.active?' <small>기록 보관</small>':''}</span></label>`).join('')}</fieldset>`).join('')}<button class="btn primary full">내 종목 저장</button></form>`);}
function rmCataloguePage(){return `<section class="panel settings-section"><div class="page-toolbar"><div><h2>1RM 공통 종목</h2><p class="field-hint">기본 6종에서 시작하며 회원은 필요한 종목만 추가합니다. 이름을 정정해도 종목 ID와 기록은 유지됩니다.</p></div><div class="rm-management-actions"><button class="btn soft" data-action="rm-categories">분류 관리</button><button class="btn primary" data-action="rm-catalogue-add">${icon('plus')}종목 추가</button></div></div>${categoryMarkup(rmCategories.map(([id,label])=>({id,label})),({id,label})=>`<section class="rm-admin-group"><h3>${label}</h3>${rmCatalogue.filter(m=>m.category===id&&!m.deleted).sort(movementOrder).map(m=>`<div class="rm-admin-row"><div><strong>${esc(m.name)}</strong><span class="mini-badge ${m.isDefault?'rm-default-badge':'rm-optional-badge'}">${!m.active?'신규 선택 중지':m.isDefault?'기본 표시':'선택 항목'}</span></div><div class="rm-catalogue-actions"><button class="icon-control" data-rm-catalogue-edit="${esc(m.id)}" aria-label="${esc(m.name)} 수정">${icon('edit')}</button><button class="icon-control danger-button" data-rm-catalogue-delete="${esc(m.id)}" aria-label="${esc(m.name)} 삭제">${icon('trash')}</button></div></div>`).join('')}</section>`,esc)}</section>`;}
function rmCatalogueForm(id=''){if(!can('rm')||memberPreview)return;const m=rmCatalogue.find(m=>m.id===id)||{name:'',category:rmCategories[0]?.[0]||'squat',isDefault:false,active:true};modal(id?'1RM 종목 수정':'1RM 종목 추가',`<form id="rm-catalogue-form" data-catalogue-id="${esc(id)}"><label class="field">종목 이름<input name="name" required minlength="2" maxlength="80" value="${esc(m.name)}" placeholder="예: Zercher Squat"></label><label class="field">분류<select name="category">${rmCategories.map(([id,label])=>`<option value="${id}" ${id===m.category?'selected':''}>${label}</option>`).join('')}</select></label><label class="checkbox-label"><input type="checkbox" name="isDefault" ${m.isDefault?'checked':''}>처음 사용하는 회원에게 기본 표시</label><label class="checkbox-label"><input type="checkbox" name="active" ${m.active?'checked':''}>회원이 이 종목을 선택하고 기록할 수 있음</label><p class="field-hint">사용을 중지해도 과거 기록은 남습니다. 기존 수업·기록은 종목 ID와 이전 이름으로 계속 연결됩니다.</p><button class="btn primary full">종목 저장</button></form>`);}
async function rmForms(f,data){if(f.id==='rm-selection-form'){state.rmSelections??={};state.rmSelections[viewer.id]=new FormData(f).getAll('rmSelection').filter(id=>allRmMovements().some(m=>m.id===id));save();close(true);render();toast('내 1RM 종목을 저장했어요.');return true}if(f.id!=='rm-catalogue-form')return false;if(!can('rm')){toast('종목 관리 권한이 필요해요.');return true}const finish=beginFormSubmit(f);if(!finish)return true;try{await request('/api/rm-catalogue',{id:f.dataset.catalogueId||undefined,name:data.name,category:data.category,isDefault:data.isDefault==='on',active:data.active==='on'});await loadServer(false);close(true);toast('1RM 종목을 저장했어요.');}catch(e){toast(e.message);}finally{finish();}return true;}
function sectionRmReference(sec,index,course=program){const names=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[],movements=[...new Set(names.map(name=>findRmMovement(rmCatalogue,name)?.id).filter(Boolean))].map(id=>rmCatalogue.find(m=>m.id===id));if(!movements.length||!movements.some(m=>best(m.id)))return '';const key=date+'_'+course+'_'+index,picked=movements.find(m=>m.id===sectionRmChoices.get(key))||movements.find(m=>best(m.id))||movements[0],record=best(picked.id);return `<div class="section-rm-reference"><div class="section-rm-heading">${movements.length>1?`<label>내 1RM 기준<select data-rm-section-index="${index}" data-rm-section-program="${course}" aria-label="비율을 확인할 운동">${movements.map(m=>`<option value="${esc(m.id)}" ${m.id===picked.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`:`<span>내 ${esc(picked.name)} 1RM 기준</span>`}${record?`<strong>${formatWeight(record.lbs)} <small>${state.unit}</small></strong>`:picked.active?`<button class="link" data-rm="${esc(picked.id)}">1RM 등록 →</button>`:'<span class="muted">기록 없음</span>'}</div>${record?`<div class="section-percentages">${rmPercentages(record.lbs).map(r=>`<div><span>${r.percent}%</span><strong>${formatWeight(r.lbs)}</strong></div>`).join('')}</div>`:''}</div>`;}
Object.assign(actions,{'rm-select':showRmPicker,'rm-catalogue-add':()=>rmCatalogueForm()});
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(d?.rmCatalogueEdit)rmCatalogueForm(d.rmCatalogueEdit);});
document.addEventListener('input',e=>{if(e.target.id!=='rm-picker-search')return;const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.rm-picker-row').forEach(row=>row.hidden=!row.dataset.rmSelectName.includes(q));document.querySelectorAll('.rm-picker-group').forEach(group=>group.hidden=![...group.querySelectorAll('.rm-picker-row')].some(row=>!row.hidden));});
document.addEventListener('change',e=>{if(e.target.dataset.rmSectionIndex===undefined)return;const i=+e.target.dataset.rmSectionIndex,course=e.target.dataset.rmSectionProgram||program;sectionRmChoices.set(date+'_'+course+'_'+i,e.target.value);e.target.closest('.section-rm-reference').outerHTML=sectionRmReference(workout(course).sections[i],i,course);});
function syncHomeTimetable(){if($('.home-timetable')?.dataset.defaultOpen==='true'){$('.home-timetable').open=true;return;}const d=$('.home-timetable'),desktop=matchMedia('(min-width:761px)').matches;if(d)d.open=homeTimetableState[desktop?'desktop':'mobile']??desktop;}
document.addEventListener('click',e=>{const summary=e.target.closest('.home-timetable>summary');if(summary)homeTimetableState[matchMedia('(min-width:761px)').matches?'desktop':'mobile']=!summary.parentElement.open;});
window.addEventListener('resize',()=>{if(page==='home')syncHomeTimetable()});

function updateHomeHeader(){clearTimeout(meetupExpiryTimer);document.body.classList.toggle('session-restoring',shared&&loading&&page==='login');const shown=!['login','push-setup','privacy-setup'].includes(page)&&viewer?.status==='approved',slot=$('#home-header-banner');if(slot){const markup=shown?homeBanner():'';slot.hidden=!markup;if(headerBannerMarkup!==markup){slot.innerHTML=markup;headerBannerMarkup=markup;}mountNoticeTicker(slot);}const meetupSlot=$('#meetup-header-banner');if(meetupSlot){const rows=shown?pinnedMeetups(state.posts,serverNow()):[],markup=rows.length?`<div class="notice meetup-notice" role="region" aria-label="운동 번개 공지"><span aria-hidden="true">⚡</span><div class="notice-track"><div class="notice-text"><span>${rows.map((p,index)=>`<button type="button" class="meetup-entry ${index%2?'meetup-entry-gold':''}" data-meetup-post="${esc(p.id)}">${esc(meetupMessage(p.starts_at))}</button>`).join('<span class="meetup-entry-divider" aria-hidden="true">│</span>')}</span></div></div><button type="button" class="meetup-open" data-meetup-post="${esc(rows[0].id)}" aria-label="운동 번개 글 열기">${icon('arrow')}</button></div>`:'';meetupSlot.hidden=!markup;if(headerMeetupMarkup!==markup){meetupSlot.innerHTML=markup;headerMeetupMarkup=markup;}mountNoticeTicker(meetupSlot);}if(shown){const time=+serverNow(),deadlines=state.posts.flatMap(p=>{const life=meetupLifecycle(p,time);return [life.closesAt,life.deletesAt].filter(t=>t!==null&&t>time);});if(deadlines.length)meetupExpiryTimer=setTimeout(refreshMeetupLifecycle,Math.min(2147483647,Math.max(10,Math.min(...deadlines)-time+10)));}const color=getComputedStyle(document.documentElement).getPropertyValue(page==='login'&&!loading?'--login-brand-bg':'--bg').trim();if(color)document.querySelector('meta[name="theme-color"]')?.setAttribute('content',color);}

function courseCard(course,visible,day){
 const w=workout(course,day);
 return `<article class="course-card ${w.sections.length?'':'is-empty-course'}" data-course="${course}" aria-label="${course} 수업"><div class="course-sections">${!visible?'<div class="empty">아직 공개되지 않은 수업이에요.<br>전날 '+releaseTime+'에 공개됩니다.</div>':!w.sections.length?`<div class="empty">${emptyWorkoutMessage(day,course)}</div>`:`${w.overviewId?`<button class="video-link workout-overview" data-video="${w.overviewId}" data-video-title="${course} 운동 설명">▶ 운동 설명 영상</button>`:''}${w.sections.map((sec,i)=>{const lines=String(sec.text||'').split('\n').filter(l=>l.trim()),preview=lines.slice(0,3).join('\n'),ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[],id='course-'+day+'-'+(course==='B/T'?'bt':'wod')+'-'+i;return `<section class="course-section-card" data-section="S${i+1}" data-expanded="true"><div class="course-section-heading"><span class="course-section-badge">S${i+1}</span></div><div class="course-section-preview" hidden>${workoutText(preview)}${lines.length>3?'\n…':''}</div><div class="course-section-full" id="${id}"><div class="exercise">${workoutText(sec.text)}</div><div class="section-movement-links">${ms.map(name=>`<button class="movement-link" data-movement="${esc(name)}">${esc(name)} ${icon('youtube')}</button>`).join('')}</div>${sectionRmReference(sec,i,course)}</div><div class="course-section-footer"><span class="section-record-kind">${sec.record?esc(sec.kind)+' 기록':''}</span><button type="button" class="course-section-toggle" data-course-toggle="S${i+1}" aria-expanded="true" aria-controls="${id}" aria-label="S${i+1} 접기">접기 −</button></div></section>`}).join('')}`}</div></article>`;
}
function toggleCourseSection(button){const section=button.closest('.course-section-card'),expanded=button.getAttribute('aria-expanded')!=='true';section.dataset.expanded=String(expanded);section.querySelector('.course-section-full').hidden=!expanded;section.querySelector('.course-section-preview').hidden=expanded;button.setAttribute('aria-expanded',String(expanded));button.setAttribute('aria-label',section.dataset.section+(expanded?' 접기':' 전체 보기'));button.textContent=expanded?'접기 −':'전체 보기 +';}

function syncHomeCards(){
 homeCardsObserver?.disconnect();const track=$('.home-course-carousel');if(!track)return;const cards=[...track.querySelectorAll('.course-card')];
 const fit=()=>{const card=cards.find(c=>c.dataset.course===program)||cards[0];if(card)track.style.height=Math.ceil(card.getBoundingClientRect().height)+'px';};
 const active=cards.find(c=>c.dataset.course===program);if(active)track.scrollLeft=active.offsetLeft;
 let timer;track.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(page!=='home'||!track.isConnected)return;const card=cards.reduce((a,b)=>Math.abs(a.offsetLeft-track.scrollLeft)<Math.abs(b.offsetLeft-track.scrollLeft)?a:b);program=card.dataset.course;document.querySelectorAll('.home-program-tabs [data-program]').forEach(b=>{b.classList.toggle('active',b.dataset.program===program);b.setAttribute('aria-pressed',String(b.dataset.program===program));});fit();},80);},{passive:true});
 track.addEventListener('toggle',()=>requestAnimationFrame(fit),true);if('ResizeObserver'in window){homeCardsObserver=new ResizeObserver(fit);cards.forEach(c=>homeCardsObserver.observe(c));}fit();
}

// Supabase writes are acknowledged before changing the visible records. Demo
// state never enters these routes and is never imported into the shared DB.
function sharedCopy(html){return html.replaceAll('운동 결과는 현재 기기에만 저장되는 미리보기입니다. 순위 참여를 꺼도 기록은 공개되는 설정입니다.','회원 기록은 서버에 저장됩니다. 순위 참여를 꺼도 운동 기록은 회원에게 공개돼요.').replaceAll('이 브라우저의 미리보기에 저장됩니다.','회원 기록으로 저장됩니다.').replaceAll('일반 게시글은 아직 현재 기기의 미리보기입니다.','일반 게시글과 댓글도 회원끼리 공유됩니다.').replaceAll('미리보기 글은 이 브라우저에만 저장됩니다.','게시글은 승인된 회원에게 공개됩니다.');}
async function sharedPostAction(path,id,remove=false){if(postPending.has(id))return;postPending.set(id,'delete');try{await request(path,{id});if(remove){state.posts=state.posts.filter(p=>p.id!==id);close(true);render();toast('게시글을 삭제했어요.');}}catch(e){toast(e.message);}finally{postPending.delete(id);}}

async function sharedForm(f,data){
 const supported=['rm-form','record-form','post-form','rm-selection-form','identity-link-form','signup-form'];
 if(!supported.includes(f.id)||f.id==='post-form'&&data.category==='공지사항')return false;
 if(['identity-link-form','signup-form'].includes(f.id)){toast('실제 가입과 이전 데이터 연결은 운영자에게 문의해주세요.');return true;}
 const buttons=[...f.querySelectorAll('button[type="submit"],button:not([type])')];buttons.forEach(b=>b.disabled=true);
 try{
  let path,payload;
  if(f.id==='rm-form'){path='/api/rms';payload={...(f.dataset.editId?{id:f.dataset.editId}:{}),movementId:data.movement,lbs:rmWeightLbs(f),date:data.date};}
  if(f.id==='rm-selection-form'){path='/api/preferences';payload={rmSelection:new FormData(f).getAll('rmSelection')};}
  if(f.id==='record-form'){
   const sec=workout(data.program,data.date).sections[+data.section];if(!sec?.record)throw Error('기록할 수업 구간을 선택해주세요.');
   const old=state.records.find(r=>r.id===f.dataset.editId),r={id:old?.id||crypto.randomUUID(),memberId:(can('records.create')||can('records.update'))?data.memberId:viewer.id,date:data.date,program:data.program,section:'S'+(+data.section+1),session:old?.session||'',note:data.note||''};
   Object.assign(r,recordInputPayload(sec,f,old));
   path='/api/records';payload={records:[r]};
  }
  if(f.id==='post-form'){const meetup=data.category==='운동 번개',startsAt=meetup?meetupStart(data.meetupDate,data.meetupTime):null;path=meetup?'/api/meetups':'/api/posts';f.dataset.photoPostId||=crypto.randomUUID();payload={id:f.dataset.photoPostId,category:data.category,title:data.title,body:data.body,photoIds:await uploadPhotos(f,request,'community'),...(meetup?{startsAt,bannerPinned:data.meetupPin==='on',sendPush:data.meetupPush==='on'}:{})};}
  await request(path,payload);await loadServer(false);unsaved.track($('#modal-body'));close(true);
  toast('저장했어요.');
 }catch(e){toast(e.message);}finally{buttons.forEach(b=>b.disabled=false);}return true;
}
if(shared){
 actions.rank=async()=>{try{await request('/api/preferences',{rank:!state.rank});await loadServer(false);toast(state.rank?'순위 참여를 켰어요.':'순위 참여를 껐어요. 기록은 계속 공개돼요.');}catch(e){toast(e.message);}};
 actions.logout=signOut;

}

function pendingAccountPage(suspended=false){const needsName=state.name==='온오프 회원';return `<section class="panel settings-section pending-wrap"><h1>${suspended?'이용이 중지된 계정이에요.':'가입 승인 대기 중이에요.'}</h1>${viewer?.email?`<p class="field-hint">로그인 이메일 · ${esc(viewer.email)}</p>`:''}<p class="muted">${suspended?'회원 상태를 운영자에게 확인해주세요.':esc(state.name)+'님의 가입 신청을 받았어요. 운영자가 승인하면 이용할 수 있어요.'}</p>${!suspended&&needsName?`<form id="profile-pending-form"><label class="field">실명<input name="name" required minlength="2" maxlength="30" value="${esc(state.name)}"></label><button class="btn primary">이름 저장</button></form>`:''}<p class="field-hint">${suspended?'': '승인 상태는 자동으로 확인합니다. 다시 가입할 필요는 없어요.'}</p><div class="pending-actions"><button class="btn primary" data-action="refresh-approval">승인 상태 확인</button><button class="btn soft" data-action="logout">로그아웃</button><button class="link" data-action="withdrawal">회원 탈퇴</button></div></section>`;}
function withdrawalForm(){if(!shared){return modal('회원 탈퇴',`<p>${globalThis.ONOFF_DEMO?'예시 앱은 실제 회원 계정이 아니므로 탈퇴할 계정이 없어요.':'이 미리보기와 회원용 앱의 계정은 별도로 관리됩니다.'}</p><a class="btn primary full" href="https://nuclearstark.github.io/Onoffgym/#login">회원용 앱 열기</a>`);}modal('회원 탈퇴',`<form id="withdrawal-form"><div class="withdrawal-warning">탈퇴하면 보유 포인트와 모든 쿠폰이 소멸되며 복구할 수 없습니다.<br><br>로그인 계정과 개인 운동기록·1RM·출석·회원권 정보, 작성한 일반 게시글·댓글이 삭제됩니다. 운영 공지는 작성자 연결을 해제해 유지합니다.<br><br>앱 탈퇴와 체육관 회원권 해지·환불은 별개입니다. 남은 회원권은 체육관에 먼저 확인해주세요.</div><label class="field">현재 비밀번호<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><label class="checkbox-label"><input type="checkbox" name="confirmed" required>삭제 내용을 확인했으며 회원 탈퇴에 동의합니다.</label><p id="withdrawal-status" role="status"></p><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn danger-button">탈퇴하고 정보 삭제</button></div></form>`);}
async function handleAccountForm(f){
 if(!['email-auth-form','withdrawal-form'].includes(f.id))return false;
 if(!f.reportValidity())return true;const b=Object.fromEntries(new FormData(f)),button=f.querySelector('button:not([type="button"])'),status=f.querySelector('[role="status"]');if(button)button.disabled=true;if(status){status.textContent='처리하고 있어요…';status.classList.remove('error');}
 try{
  if(f.id==='withdrawal-form'){
   if(!b.confirmed)throw Error('삭제 내용에 동의해주세요.');await request('/api/account/delete',{password:b.password,confirmed:true});unsaved.track(f);try{await (await deviceSubscription())?.unsubscribe();}catch{}try{await emailAuth.signOut();}catch{}await purgePhotoStorage();for(const key of ['onoff-display','onoff-push-preferences','onoff-password-recovery']){localStorage.removeItem(key);sessionStorage.removeItem(key);}close(true);history.scrollRestoration='manual';scrollAppTo(0,0);location.replace(location.pathname+'#login');location.reload();return true;
  }
  if(!shared)throw Error('실제 회원용 앱에서 이용해주세요.');const mode=f.dataset.mode;
  if(['signup','reset'].includes(mode)&&b.password!==b.confirmPassword)throw Error('두 비밀번호가 일치하지 않아요.');
  if(mode==='forgot'){await emailAuth.requestReset(b.email);status.textContent='가입된 이메일이라면 재설정 링크를 보내드려요. 받은편지함과 스팸함을 확인해주세요.';unsaved.track(f);return true;}
  if(mode==='reset'){const session=await emailAuth.session();if(!session||sessionStorage.getItem('onoff-password-recovery')!==session.user.id)throw Error('재설정 링크를 다시 요청해주세요.');await emailAuth.updatePassword(b.password);sessionStorage.removeItem('onoff-password-recovery');authMode='login';authNotice='비밀번호를 변경했어요.';unsaved.track(f);page='home';location.hash='home';await loadServer();return true;}
  if(mode==='signup'){if(!b.privacy)throw Error('개인정보 수집·이용에 동의해주세요.');if(!b.ageOver14)throw Error('만 14세 이상만 가입할 수 있어요.');await emailAuth.signUp(b.email,b.password,b.name,{ageOver14:b.ageOver14==='on',disclosure:b.disclosure==='on',gender:b.gender});}else await emailAuth.signIn(b.email,b.password);
  authNotice='';unsaved.track(f);page='home';history.replaceState(null,'','#home');await loadServer();if(approvalTarget&&viewer?.role==='admin')go('admin/members');
 }catch(e){if(status){status.textContent=e.message;status.classList.add('error');}else toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}return true;
}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]')?.dataset.authMode;if(!['login','signup','forgot'].includes(mode))return;const f=$('#email-auth-form');if(f)unsaved.track(f);authMode=mode;sessionStorage.removeItem('onoff-password-recovery');authNotice='';render();});
