function approvalRequestNotice(){if(!approvalTarget)return '';const member=state.members.find(m=>m.id===approvalTarget);return `<section class="panel approval-request-note"><strong>${member?.status==='pending'?esc(member.name)+'님의 가입 승인 요청':member?.status==='approved'?'이미 승인된 회원이에요.':'이미 처리되었거나 삭제된 가입 요청이에요.'}</strong>${member?`<button class="btn soft" data-member-detail="${esc(member.id)}">회원 상세 확인</button>`:''}</section>`;}

function memberRolePanel(member){return `<section class="membership-section member-role-panel"><h3>권한·승인 상태</h3>${accountRetentionNotice(member)}${member.id===viewer.id?`<p class="field-hint">본인 권한은 다른 운영자가 변경할 수 있어요.</p>`:`<form id="member-role-form" data-member-id="${esc(member.id)}"><label class="field">계정 권한<select name="role"><option value="member" ${member.role==='member'?'selected':''}>회원</option><option value="coach" ${member.role==='coach'?'selected':''}>코치</option><option value="admin" ${member.role==='admin'?'selected':''}>운영자</option></select></label><label class="field">계정 상태<select name="status">${[['pending','승인 대기'],['approved','승인'],['suspended',member.approved_at?'이용 중지':'승인 거절']].map(([value,label])=>`<option value="${value}" ${member.status===value?'selected':''}>${label}</option>`).join('')}</select></label>${coachPermissionsMarkup(member,{escape:esc})}<button class="btn primary full" type="submit">권한 저장</button></form>`}${member.id!==viewer.id?`<button type="button" class="btn danger-button full account-delete-launch" data-admin-account-delete="${esc(member.id)}">${icon('trash')}계정 삭제</button>`:''}</section>`;}

function applyAvatar(emoji){state.avatarByMember??={};state.avatarByMember[viewer.id]=emoji;state.members.filter(m=>m.id===viewer.id).forEach(m=>m.avatarEmoji=emoji);state.records.filter(isOwnRecord).forEach(r=>r.avatarEmoji=emoji);document.querySelectorAll('.settings-avatar,.profile-avatar,.profile-button .avatar').forEach(el=>el.textContent=emoji);document.querySelectorAll('[data-avatar-emoji]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.avatarEmoji===emoji)));}
async function chooseAvatar(emoji){
 if(!AVATAR_EMOJIS.includes(emoji))return;avatarConfirmed??=avatarEmoji(state.avatarByMember?.[viewer.id]);avatarRevision++;avatarQueued=emoji;avatarPending=true;applyAvatar(emoji);if($('#avatar-save-status'))$('#avatar-save-status').textContent='저장 중…';if(avatarSaving)return;avatarSaving=true;
 try{while(avatarQueued){const value=avatarQueued;avatarQueued=null;try{if(shared||globalThis.ONOFF_DEMO)await request('/api/preferences',{avatarEmoji:value});else save();avatarConfirmed=value;if(!avatarQueued)applyAvatar(value);if(!avatarQueued&&$('#avatar-save-status'))$('#avatar-save-status').textContent='저장했어요.';}catch(e){if(!avatarQueued){applyAvatar(avatarConfirmed);if($('#avatar-save-status'))$('#avatar-save-status').textContent='저장하지 못했어요. 다시 선택해주세요.';toast(e.message);}}}}finally{avatarSaving=false;avatarPending=false;}
}

function confirmWorkoutDelete(key){if(!can('workouts.delete')||memberPreview)return;const w=state.workouts[key];if(!w)return;modal('수업 삭제',`<p>${esc(w.date)} · ${esc(w.program)} 수업을 삭제할까요?</p><p class="field-hint">등록한 운동 내용과 특별 수업 일정이 삭제됩니다. 회원이 이미 입력한 운동기록과 1RM은 보관됩니다.</p><div class="form-footer"><button class="btn" data-action="close">취소</button><button class="btn danger-button" data-confirm-workout-delete="${esc(key)}">수업 삭제</button></div>`);}
