function scheduleWorkoutDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(()=>flushWorkoutDraft(),250);}
function flushWorkoutDraft(force=false){clearTimeout(draftTimer);const f=draftForm;if(!f?.isConnected||f!==$('#workout-form'))return;const value=readWorkoutEditor(f),snapshot=JSON.stringify(value);if(!force&&snapshot===draftBaseline)return;try{drafts.write(viewer.id,f.dataset.date,f.dataset.program,value);draftBaseline=snapshot;const status=$('#workout-draft-status');if(status)status.textContent='임시저장됨 · 이 기기에서 이어서 작성할 수 있어요.';unsaved.track($('#modal-body'));}catch{if($('#workout-draft-status'))$('#workout-draft-status').textContent='임시저장 실패 · 수업 저장을 눌러주세요.';}}
function clearWorkoutDraft(f){clearTimeout(draftTimer);drafts.remove(viewer.id,f.dataset.date,f.dataset.program);draftForm=null;}
function redrawWorkoutSections(sections){const f=$('#workout-form');if(!f)return;f.dataset.count=sections.length;$('#workout-sections').innerHTML=sections.map(editorSection).join('');mountSectionEditor(f,sections.length-1);flushWorkoutDraft(true);}
function removeWorkoutSection(index){const f=$('#workout-form');if(!f)return;const value=readWorkoutEditor(f);if(value.sections.length===1)return toast('수업에는 최소 한 개의 구간이 필요해요.');if(!Number.isInteger(index)||index<0||index>=value.sections.length)return;value.sections.splice(index,1);redrawWorkoutSections(value.sections);}
function openWorkoutCopy(key=''){
 if(!coach||memberPreview)return;const courses=Object.values(state.workouts).sort((a,b)=>b.date.localeCompare(a.date)||a.program.localeCompare(b.program));if(!courses.length)return toast('복사할 수업이 아직 없어요.');const source=state.workouts[key]||courses[0];modal('지난 수업 복사',`<form id="workout-copy-form"><label class="field">원본 수업<select name="source">${courses.map(w=>`<option value="${esc(w.date+'_'+w.program)}" ${w===source?'selected':''}>${esc(w.date)} · ${esc(w.program)} · ${w.sections.length}개 구간</option>`).join('')}</select></label><label class="field">복사할 날짜<input name="date" type="date" required value="${date}"></label><label class="field">수업<select name="program"><option ${source.program==='B/T'?'selected':''}>B/T</option><option ${source.program==='WOD'?'selected':''}>WOD</option></select></label><p class="field-hint">원본 수업은 유지됩니다. 복사한 내용은 편집 화면에서 확인한 후 수업 저장을 눌러야 반영됩니다.</p><button class="btn primary full">복사해서 편집하기</button></form>`);}
Object.assign(actions,{'add-section':()=>{const f=$('#workout-form');if(!f)return;const value=readWorkoutEditor(f);if(value.sections.length>=99)return toast('구간은 최대 99개까지 추가할 수 있어요.');value.sections.push({title:'',text:'',record:false,kind:'중량',movements:[]});redrawWorkoutSections(value.sections);},'copy-workout':()=>openWorkoutCopy(),'discard-workout-draft':()=>{const f=$('#workout-form');if(!f||!confirm('이 기기에 임시저장한 초안을 지우고 등록된 수업으로 돌아갈까요?'))return;const p=f.dataset.program;clearWorkoutDraft(f);unsaved.track($('#modal-body'));workoutForm(p);},'pending-members':()=>{memberRoleFilter='all';memberFilter='pending';memberSearch='';render();}});
