document.addEventListener('submit',e=>{if(e.target.id!=='workout-copy-form')return;e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),source=state.workouts[b.source];if(!source||!b.date)return;const targetDraft=drafts.read(viewer.id,b.date,b.program);if(targetDraft&&!confirm('대상 날짜에 임시저장한 초안이 있어요. 복사한 내용으로 초안을 교체할까요?'))return;const existing=state.workouts[b.date+'_'+b.program];if(existing&&!confirm('대상 날짜에 수업이 있어요. 편집 후 저장하면 해당 수업을 덮어씁니다. 계속할까요?'))return;date=b.date;unsaved.track($('#modal-body'));workoutForm(b.program,{copied:{...structuredClone(source),date,program:b.program,sessions:[],overview:source.overviewId?'https://youtu.be/'+source.overviewId:''}});});
