function homeTimetable(slots,session,day){
 const rest=!slots.length,restText='쉬는것도 운동의 일부',title=day===today()?'오늘의':dateLabel(day);
 return `<details class="panel home-timetable" data-default-open="${rest||slots.every(s=>s.type==='OPEN GYM')}" ${rest||slots.every(s=>s.type==='OPEN GYM')?'open':''}><summary class="panel-head"><h2>${title} 타임테이블</h2><span class="timetable-toggle">${icon('clock')}<span>시간표 보기</span></span></summary>${rest?`<div class="rest-day-message"><strong>${restText}</strong><p>주말 잘보내세요!</p></div>`:`<div class="schedule">${slots.map(x=>`<button class="schedule-row ${x.type==='B/T'?'sched-bt':x.type==='WOD'?'sched-wod':'sched-open'} ${session?.time===x.time?'active':''}" data-session="${x.time}"><span class="sched-time">${x.time}</span><strong>${x.type}</strong><small>${day===today()&&minutes(x.end)<=seoulNow()?'종료':session?.time===x.time?(session.current?'진행 중':'선택'):x.type==='OPEN GYM'?'자유':'60분'}</small></button>`).join('')}</div><div class="schedule-foot">예약 없이 자유롭게 참여하세요.<span>평일 오픈짐 12:00–16:30 · 토요일 10:00–20:00</span></div>`}</details>`;
}
