async function markCommunityRead(post){if(!viewer||post.authorId===viewer.id||post.author_id===viewer.id)return;const key=communityKey(post);if(communityReads[key]||communityPendingReads.has(key))return;communityPendingReads.add(key);communityReads[key]=serverNow().toISOString();nav();try{if(shared)await request('/api/community/read',{id:post.id,kind:post.serverNotice?'notice':'post'});else{state.communityReadsByMember??={};state.communityReadsByMember[viewer.id]={...communityReads};save();}}catch(e){delete communityReads[key];nav();toast(e.message);}finally{communityPendingReads.delete(key);}}

