installStandardControls(document);

let schedulePast=false,scheduleSearch='',schedulePageIndex=0;
function schedulePage(){const groups=new Map();for(const w of Object.values(state.workouts).sort((a,b)=>a.date.localeCompare(b.date)||a.program.localeCompare(b.program))){if(scheduleSearch?w.date!==scheduleSearch:schedulePast?w.date>=today():w.date<today())continue;if(!groups.has(w.date))groups.set(w.date,[]);groups.get(w.date).push(w);}const days=[...groups],pages=Math.max(1,Math.ceil(days.length/5));schedulePageIndex=Math.min(schedulePageIndex,pages-1);return `<div class="schedule-settings-stack" id="schedule-page" data-pages="${pages}">${can('release')?adminContent('release'):''}<section class="panel settings-section"><h2>등록 일정</h2><div class="schedule-filter-row"><label class="schedule-date-control"><span>날짜 검색</span><span class="schedule-date-visible">${icon('calendar')}<span>${scheduleSearch?dateLabel(scheduleSearch):'날짜 선택'}</span><span aria-hidden="true">⌄</span></span><input id="schedule-date-search" type="date" value="${scheduleSearch}" aria-label="등록 일정 날짜 검색"></label><button class="btn soft" data-schedule-past>${schedulePast?'오늘 이후':'지난 수업'}</button>${scheduleSearch?'<button class="link" data-schedule-reset>검색 초기화</button>':''}</div>${days.slice(schedulePageIndex*5,schedulePageIndex*5+5).map(([day,ws])=>`<div class="schedule-day"><strong>${esc(day)}</strong>${ws.map(w=>`<div class="history-row"><span>${w.program} <small>${isReleased(day,serverNow())?'공개 중':'공개 예정'}</small></span><div class="workout-row-actions"><button class="icon-btn" data-workout-date="${day}" data-workout-program="${w.program}" aria-label="${day} ${w.program} 수정">${icon('edit')}</button><button class="icon-btn" data-delete-workout="${day}_${w.program}" aria-label="${day} ${w.program} 삭제">${icon('close')}</button></div></div>`).join('')}</div>`).join('')||'<div class="empty">등록된 일정이 없어요.</div>'}<div class="page-toolbar"><button class="btn" data-schedule-shift="-1" ${schedulePageIndex===0?'disabled':''} aria-label="이전 5일">‹</button><span>${schedulePageIndex+1} / ${pages}</span><button class="btn" data-schedule-shift="1" ${schedulePageIndex>=pages-1?'disabled':''} aria-label="다음 5일">›</button></div></section></div>`;}
document.addEventListener('change',e=>{if(e.target.id==='schedule-date-search'){scheduleSearch=e.target.value;if(scheduleSearch)date=scheduleSearch;schedulePageIndex=0;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-schedule-past')){schedulePast=!schedulePast;scheduleSearch='';schedulePageIndex=0;render();}if(b.hasAttribute('data-schedule-reset')){scheduleSearch='';schedulePageIndex=0;render();}if(b.dataset.scheduleShift){schedulePageIndex=Math.max(0,schedulePageIndex+Number(b.dataset.scheduleShift));render();}});



document.addEventListener('click',async e=>{const b=e.target.closest('[data-record-delete]');if(!b)return;if(!confirm('이 구간의 기록을 삭제할까요? 연결된 1RM 이력도 삭제됩니다.'))return;b.disabled=true;try{await request('/api/records/delete',{id:b.dataset.recordDelete});await loadServer(false);close(true);toast('구간 기록을 삭제했어요.');}catch(e){toast(e.message);b.disabled=false;}});

function dailyPhotos(){const items=photos.filter(p=>p.kind==='daily'&&p.date===date&&(p.program==='ALL'||p.program===recordsFilter));if(!shared)return '';return `<section class="panel settings-section daily-photos" id="daily-record-photos"><div class="panel-head"><h2>오늘의 기록</h2>${can('photos')?'<button class="btn soft" data-action="daily-photo-upload">사진 올리기</button>':''}</div>${items.length?items.map(p=>`<div class="daily-photo-class"><div class="daily-photo-label"><small>${p.program==='ALL'?'공통 · ':''}${esc(p.session||'수업 전체')}</small>${can('photos')?`<button type="button" class="link" data-photo-program="${p.id}">수업 구분</button>`:''}</div>${photoGallery([p],{editable:can('photos')})}</div>`).join(''):'<p class="daily-photo-empty">이 날짜의 기록이 아직 없어요.</p>'}</section>`;}
Object.assign(actions,{'daily-photo-upload':()=>{if(!shared||!can('photos'))return;modal('오늘의 기록',`<form id="daily-photo-form"><label class="field">날짜<input name="date" type="date" value="${date}" required></label><label class="field">수업<select name="program"><option value="ALL" selected>공통 (B/T·WOD)</option><option>B/T</option><option>WOD</option></select></label><label class="field">수업 시작 시각 · 선택<input name="session" type="time"></label>${photoPicker()}<p class="field-hint">회원별 기록 입력 없이 사진만 저장해도 됩니다.</p><button class="btn primary full">오늘의 기록 저장</button></form>`);}});
document.addEventListener('submit',async e=>{if(e.target.id!=='daily-photo-form')return;e.preventDefault();const f=e.target;if(!f.reportValidity())return;const b=f.querySelector('[type=submit],button:not([type])');b.disabled=true;try{const photoIds=await uploadPhotos(f,request,'daily');if(!photoIds.length)throw Error('사진을 선택해주세요.');await request('/api/photos/attach',{kind:'daily',...Object.fromEntries(new FormData(f)),photoIds});date=f.elements.date.value;if(f.elements.program.value!=='ALL')recordsFilter=f.elements.program.value;await loadServer(false);close(true);go('members');toast('오늘의 기록을 저장했어요.');}catch(e){toast(e.message);}finally{b.disabled=false;}});
document.addEventListener('click',async e=>{const open=e.target.closest('[data-photo-open]'),del=e.target.closest('[data-photo-delete]');if(open){e.preventDefault();try{await showPhoto(open.dataset.photoOpen,request,open);}catch(e){toast(e.message);}}if(del&&(can('photos')||can('notices'))&&confirm('이 사진을 삭제할까요?')){del.disabled=true;try{await request('/api/photos/delete',{id:del.dataset.photoDelete});forgetPhoto(del.dataset.photoDelete);const noticeId=del.closest('#notice-post-form')?.dataset.noticeId;await loadServer(false);if(noticeId)del.closest('.photo-tile')?.remove();toast('사진을 삭제했어요.');}catch(e){toast(e.message);del.disabled=false;}}});

function mountScheduleSwipe(){const root=$('#schedule-page');if(!root)return;let start=null;root.addEventListener('touchstart',e=>{start=null;if(e.touches.length!==1||e.target.closest('input,textarea,select,button,a')||String(window.getSelection()))return;start={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});root.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;start=null;if(Math.abs(dx)<65||Math.abs(dx)<Math.abs(dy)*2)return;const next=Math.max(0,Math.min(Number(root.dataset.pages)-1,schedulePageIndex+(dx<0?1:-1)));if(next!==schedulePageIndex){schedulePageIndex=next;render();}},{passive:true});}

function isWednesday(day){return new Date(day+'T12:00:00+09:00').getUTCDay()===3;}
function homeSessionBadge(session,status,day){const label=status==='다가오는 수업'?'COMING UP':status==='진행 중'?'IN PROGRESS':status==='수업 종료'?'FINISHED':status==='선택한 수업'?'SELECTED CLASS':'SELECTED DATE';return `<div class="next-class ${session?.current?'is-current':''}"><span class="next-class-label">${session?label:'REST DAY'}</span><div class="next-class-detail">${session?`<strong>${esc(session.time)}<span>–</span>${esc(session.end)}</strong><span class="next-class-kind ${session.type==='B/T'?'kind-bt':'kind-wod'}">${esc(session.type)}</span>`:`<strong class="rest-caption" data-rest-caption>${esc(holidayState.dates[day]?.name||'휴강일')}</strong>`}</div></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-photo-program]');if(!b||!can('photos'))return;const p=photos.find(x=>x.id===b.dataset.photoProgram);if(!p)return;modal('사진 수업 구분',`<form id="photo-program-form" data-photo-id="${p.id}"><label class="field">수업<select name="program">${[['ALL','공통 (B/T·WOD)'],['B/T','B/T'],['WOD','WOD']].map(([v,label])=>`<option value="${v}" ${p.program===v?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn primary full">구분 저장</button></form>`);});
document.addEventListener('submit',async e=>{if(e.target.id!=='photo-program-form')return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await request('/api/photos/program',{id:f.dataset.photoId,program:f.elements.program.value});await loadServer(false);close(true);toast('수업 구분을 저장했어요.');}catch(e){toast(e.message);b.disabled=false;}});
function syncWorkoutCopy(f){if(!f)return;const wed=isWednesday(f.elements.date.value),option=[...f.elements.program.options].find(o=>o.value==='B/T');if(option)option.disabled=wed;if(wed)f.elements.program.value='WOD';}
document.addEventListener('change',e=>syncWorkoutCopy(e.target.closest('#workout-copy-form')));

// A shared photograph stays mounted when only the record program changes.
function switchRecordProgram(next){if(recordsFilter===next)return;const oldIds=dailyPhotoIds();recordsFilter=next;resultSection=null;document.querySelectorAll('[data-records-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.recordsFilter===next);b.setAttribute('aria-pressed',String(b.dataset.recordsFilter===next));});const panel=$('#member-record-results');if(panel)panel.innerHTML=`<div class="panel-head"><h2>${dateLabel(date)} · ${recordsFilter}</h2>${unitToggle()}</div>${resultTable(recordsFilter)}`;mountRecordPages();if(oldIds!==dailyPhotoIds()){$('#daily-record-photos')?.remove();panel?.insertAdjacentHTML('beforebegin',dailyPhotos());mountPhotoImages($('#daily-record-photos'),request);}}
function dailyPhotoIds(){return photos.filter(p=>p.kind==='daily'&&p.date===date&&(p.program==='ALL'||p.program===recordsFilter)).map(p=>p.id).join('|');}
function videoFrame(id,title){return /^[A-Za-z0-9_-]{11}$/.test(id||'')?`<div class="embedded-video"><iframe src="https://www.youtube-nocookie.com/embed/${id}?playsinline=1&rel=0" title="${esc(title)} 동작 설명 영상" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>`:'<div class="empty">운동 설명 영상을 준비 중이에요.</div>';}
function categoryOptions(id,exclude=''){return videoCategories.filter(c=>c[0]!==exclude).map(([key,label])=>`<option value="${esc(key)}" ${key===id?'selected':''}>${esc(label)}</option>`).join('');}
function categoryManager(){if(!can('videos'))return;modal('운동 영상 대분류',`<div class="video-category-list">${videoCategories.map(([id,label])=>`<div class="history-row"><strong>${esc(label)}</strong><div><button class="icon-control" data-category-edit="${esc(id)}" aria-label="${esc(label)} 수정">${icon('edit')}</button><button class="icon-control danger-button" data-category-remove="${esc(id)}" aria-label="${esc(label)} 삭제" ${videoCategories.length<=1?'disabled':''}>${icon('trash')}</button></div></div>`).join('')}</div><button class="btn primary full" data-action="category-add">${icon('plus')}분류 추가</button>`);}
function categoryForm(id='',remove=false){if(!can('videos'))return;const category=videoCategories.find(c=>c[0]===id);modal(remove?'대분류 삭제':id?'대분류 수정':'대분류 추가',`<form id="video-category-form" data-category-action="${remove?'delete':id?'edit':'add'}" data-category-id="${esc(id)}">${remove?`<p><strong>${esc(category?.[1])}</strong> 분류의 동작을 어디로 옮길까요?</p><label class="field">옮길 대분류<select name="targetId" required>${categoryOptions('',id)}</select></label><p class="field-hint">동작과 기존 운동·1RM 기록은 유지됩니다.</p>`:`<label class="field">분류 이름<input name="label" required maxlength="40" value="${esc(category?.[1]||'')}" placeholder="분류 이름"></label>`}<button class="btn primary full">${remove?'옮긴 후 분류 삭제':'저장'}</button><p class="form-error" role="status"></p></form>`);}
Object.assign(actions,{'video-categories':categoryManager,'category-add':()=>categoryForm()});
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.categoryEdit)categoryForm(d.categoryEdit);if(d.categoryRemove)categoryForm(d.categoryRemove,true);if(d.movementRemove&&can('videos'))modal('운동 동작 삭제',`<p><strong>${esc(d.movementRemove)}</strong> 동작을 영상 목록에서 삭제할까요?</p><p class="field-hint">기존 수업과 운동·1RM 기록은 유지됩니다.</p><div class="form-footer"><button class="btn" data-movement="${esc(d.movementRemove)}">돌아가기</button><button class="btn primary" data-movement-delete-confirm="${esc(d.movementRemove)}">삭제하기</button></div>`);if(d.movementDeleteConfirm&&can('videos'))runCatalogueMutation(e.target.closest('button'),'/api/movements/delete',{name:d.movementDeleteConfirm});});
async function runCatalogueMutation(button,path,payload){button.disabled=true;try{await request(path,payload);libraryCategory='all';await loadServer(false);close(true);toast('저장했어요.');}catch(e){toast(e.message);}finally{button.disabled=false;}}
document.addEventListener('submit',async e=>{if(e.target.id!=='video-category-form')return;e.preventDefault();const f=e.target;if(!f.reportValidity())return;await runCatalogueMutation(f.querySelector('button:not([type=button])'),'/api/video-categories',{...Object.fromEntries(new FormData(f)),action:f.dataset.categoryAction,id:f.dataset.categoryId});});
function accCard(day){const a=accWorkouts[day];if(!a?.text)return '';const lines=a.text.split('\n').filter(x=>x.trim()),id='acc-content-'+day;return `<section class="panel acc-workout"><div class="panel-head"><h2>ACC Workout<span>(Optional)</span></h2></div><section class="course-section-card acc-section-card" data-section="ACC" data-expanded="true"><div class="course-section-preview" hidden>${workoutText(lines.slice(0,3).join('\n'))}${lines.length>3?'\n…':''}</div><div class="course-section-full" id="${id}"><div class="exercise">${workoutText(a.text)}</div><div class="section-movement-links">${(a.movements||[]).map(name=>`<button class="movement-link" data-movement="${esc(name)}">${esc(name)} ${icon('youtube')}</button>`).join('')}</div>${a.overviewId?videoFrame(a.overviewId,'ACC Workout'):''}</div><div class="course-section-footer"><span>Optional</span><button type="button" class="course-section-toggle" data-course-toggle="ACC" aria-expanded="true" aria-controls="${id}" aria-label="ACC 접기">접기 −</button></div></section></section>`;}
function accEditor(){const a=accWorkouts[date],editable=can(a?'acc.update':'acc.create');return `<section class="panel settings-section acc-editor">${datePicker()}<p class="field-hint">${date} · ${a?'등록됨':'미등록'} · 수업과 같은 공개 시각에 표시됩니다.</p><form id="acc-form" data-date="${date}"><fieldset ${editable?'':'disabled'}><label class="field">운동 내용<textarea name="text" required maxlength="5000" rows="7" placeholder="선택 운동을 입력해주세요.">${esc(a?.text||'')}</textarea></label><label class="field movement-picker">관련 동작 · 선택<input data-movement-input role="combobox" aria-expanded="false" aria-controls="acc-suggestions" aria-autocomplete="list" name="movements" value="${esc((a?.movements||[]).join(', '))}" maxlength="2500" autocomplete="off" placeholder="동작 검색 · 여러 개는 쉼표로 구분"><div class="movement-suggestions" id="acc-suggestions" role="listbox" hidden></div></label></fieldset><div class="form-footer">${a&&can('acc.delete')?`<button type="button" class="btn danger-button icon-control" data-acc-delete="${date}" aria-label="ACC 운동 삭제">${icon('trash')}</button>`:''}${editable?'<button class="btn primary">ACC 운동 저장</button>':''}</div><p role="status" class="acc-error"></p></form></section>`;}
function mountAcc(){const form=$('#acc-form');if(!form)return;const input=form.elements.movements;if(!input.matches(':disabled'))mountMovementAutocomplete(form,()=>libraryState.map(m=>m.name));}
document.addEventListener('submit',async e=>{if(e.target.id!=='acc-form')return;e.preventDefault();const f=e.target;if(!f.reportValidity())return;const b=f.querySelector('button:not([type])');if(!b)return;b.disabled=true;try{const data=Object.fromEntries(new FormData(f));await request('/api/acc',{...data,date:f.dataset.date,movements:(data.movements||'').split(/[;,\n]/).map(x=>x.trim()).filter(Boolean)});unsaved.track(f);await loadServer(false);toast('ACC 운동을 저장했어요.');}catch(error){f.querySelector('.acc-error').textContent=error.message;}finally{b.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-acc-delete]');if(!b||!can('acc.delete')||!confirm('이 날짜의 ACC 운동을 삭제할까요?'))return;b.disabled=true;try{await request('/api/acc',{date:b.dataset.accDelete,action:'delete'});await loadServer(false);toast('ACC 운동을 삭제했어요.');}catch(error){toast(error.message);b.disabled=false;}});

installPointsUI({request,reload:()=>loadServer(false),modal,close,toast,go,isAdmin:()=>viewer?.role==='admin'&&!memberPreview,track:root=>unsaved.track(root)});

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!can('rm'))return;if(b.dataset.rmCatalogueDelete){const m=rmCatalogue.find(m=>m.id===b.dataset.rmCatalogueDelete);if(!m)return;modal('1RM 종목 삭제',`<p><strong>${esc(m.name)}</strong> 종목을 관리·신규 선택 목록에서 삭제할까요?</p><p class="field-hint">기존 운동·1RM 기록은 보존됩니다.</p><button class="btn primary full" data-rm-catalogue-delete-confirm="${esc(m.id)}">종목 삭제</button>`);}if(b.dataset.rmCatalogueDeleteConfirm){b.disabled=true;try{await request('/api/rm-catalogue/delete',{id:b.dataset.rmCatalogueDeleteConfirm});await loadServer(false);close(true);toast('종목을 삭제했어요. 기존 기록은 유지됩니다.');}catch(error){toast(error.message);b.disabled=false;}}});

function rmCategoryManager(){if(!can('rm'))return;modal('1RM 대분류',`<div class="video-category-list">${rmCategories.map(([id,label])=>`<div class="history-row"><strong>${esc(label)}</strong><div><button class="icon-control" data-rm-category-edit="${esc(id)}" aria-label="${esc(label)} 수정">${icon('edit')}</button><button class="icon-control danger-button" data-rm-category-delete="${esc(id)}" aria-label="${esc(label)} 삭제" ${rmCategories.length<=1?'disabled':''}>${icon('trash')}</button></div></div>`).join('')}</div><button type="button" class="btn primary full" data-rm-category-add>${icon('plus')}분류 추가</button>`);}
function rmCategoryForm(id='',remove=false){if(!can('rm'))return;const category=rmCategories.find(c=>c[0]===id);modal(remove?'1RM 대분류 삭제':id?'1RM 대분류 수정':'1RM 대분류 추가',`<form id="rm-category-form" data-id="${esc(id)}" data-operation="${remove?'delete':id?'edit':'add'}">${remove?`<p><strong>${esc(category?.[1])}</strong>의 종목을 옮긴 뒤 분류를 삭제해요. 종목 ID와 기존 기록은 유지됩니다.</p><label class="field">옮길 대분류<select name="targetId" required>${rmCategories.filter(c=>c[0]!==id).map(([key,label])=>`<option value="${esc(key)}">${esc(label)}</option>`).join('')}</select></label>`:`<label class="field">분류 이름<input name="label" required maxlength="40" value="${esc(category?.[1]||'')}"></label>`}<button class="btn primary full">${remove?'옮긴 후 삭제':'저장'}</button><p class="form-error" role="status"></p></form>`);}
Object.assign(actions,{'rm-categories':rmCategoryManager});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-rm-category-add'))rmCategoryForm();if(b.dataset.rmCategoryEdit)rmCategoryForm(b.dataset.rmCategoryEdit);if(b.dataset.rmCategoryDelete)rmCategoryForm(b.dataset.rmCategoryDelete,true);});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='rm-category-form')return;e.preventDefault();if(!can('rm')||!f.reportValidity())return;const finish=beginFormSubmit(f);if(!finish)return;try{await request('/api/rm-categories',{...Object.fromEntries(new FormData(f)),action:f.dataset.operation,id:f.dataset.id});unsaved.track(f);await loadServer(false);close(true);rmCategoryManager();toast('1RM 대분류를 저장했어요.');}catch(error){f.querySelector('.form-error').textContent=error.message;}finally{finish();}});

function newCommunityPost(){
 const notice=can('notices');if(modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category" id="post-category">${notice?'<option>공지사항</option>':''}<option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="100"></label><label class="field">내용<textarea name="body" required maxlength="5000"></textarea></label><div class="meetup-date-fields" hidden><div class="field-row"><label class="field">운동 시작 날짜<input type="date" name="meetupDate" value="${today()}" required></label><label class="field">운동 시작 시간<input type="time" name="meetupTime" required></label></div><label class="checkbox-label"><input type="checkbox" name="meetupPin">홈 배너에 고정</label><label class="checkbox-label"><input type="checkbox" name="meetupPush">공지 푸시 보내기</label></div>${notice?'<label class="checkbox-label" id="post-pin-label"><input name="pinned" type="checkbox">커뮤니티 상단에 고정</label><label class="checkbox-label notice-push-option"><input name="sendPush" type="checkbox">알림을 켠 회원에게 공지 푸시 보내기</label>':''}${shared?photoPicker():''}<p class="field-hint">사진은 승인된 회원에게 공개됩니다.</p><button class="btn primary full">게시글 등록</button></form>`)===false)return;
 const form=$('#post-form');syncMeetupFields(form);form.elements.category.addEventListener('change',()=>syncMeetupFields(form));queueMicrotask(()=>unsaved.track(form));
}
function syncMeetupFields(form){if(!form)return;const meetup=form.elements.category.value==='운동 번개',notice=form.elements.category.value==='공지사항',box=form.querySelector('.meetup-date-fields');box.hidden=!meetup;box.querySelectorAll('input').forEach(el=>el.disabled=!meetup);form.elements.title.maxLength=notice?100:80;form.elements.body.maxLength=notice?5000:3000;form.querySelectorAll('#post-pin-label,.notice-push-option').forEach(label=>{label.hidden=!notice;label.querySelector('input').disabled=!notice;});}
function openMeetupPost(id){if(go('community')!==false)postModal(id);}
function maybeOpenLinkedPost(){if(linkedPostOpened||!linkedPost||viewer?.status!=='approved'||page==='push-setup')return;if(state.posts.some(p=>p.id===linkedPost)){linkedPostOpened=true;openMeetupPost(linkedPost);}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-meetup-post]');if(button)openMeetupPost(button.dataset.meetupPost);});
document.addEventListener('change',async e=>{const input=e.target;if(!input.matches('[data-meetup-pin]'))return;input.disabled=true;try{await request('/api/meetups/pin',{id:input.dataset.meetupPin,pinned:input.checked});await loadServer(false);const scroll=$('.modal-content')?.scrollTop||0;close(true);postModal(input.dataset.meetupPin);if($('.modal-content'))$('.modal-content').scrollTop=scroll;}catch(error){input.checked=!input.checked;toast(error.message);}finally{input.disabled=false;}});
async function finishPushWelcome(enable){const root=$('.push-welcome');if(!root||root.dataset.busy)return;root.dataset.busy='1';const status=root.querySelector('[role=status]');root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(enable){const support=pushSupport();if(!support.ok){status.textContent=support.reason;return;}await enablePush(pushState.publicKey,pushPreferences,request);}await request('/api/preferences',{pushOnboardingSeen:true});pushOnboardingPending=false;page='home';history.replaceState(null,'','#home');await loadServer(false);maybeOpenLinkedPost();}catch(error){status.textContent=error.message;}finally{delete root.dataset.busy;root.querySelectorAll('button').forEach(b=>b.disabled=false);}}
document.addEventListener('click',e=>{if(e.target.closest('[data-push-onboard-enable]'))finishPushWelcome(true);if(e.target.closest('[data-push-onboard-skip]'))finishPushWelcome(false);});

window.addEventListener('pageshow',updateHomeHeader);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateHomeHeader();});

installAppRelease({canReload:()=>!unsaved.hasChanges()});

function mountCommunityPages(){const root=$('.community-pages');if(!root)return;const total=allPosts().filter(p=>boardFilter==='전체'||p.category===boardFilter).length;communityPage=Math.max(0,Math.min(communityPage,Math.max(0,Math.ceil(total/5)-1)));mountSwipePages(root,{page:communityPage,onPage:index=>communityPage=index});}
let comparisonRequest=0;
async function showRmComparison(id){const m=rmMovement(id);if(!m)return;const requestId=++comparisonRequest;if(modal(esc(m.name)+' · 체육관 내 기록','<div class="rm-comparison" data-comparison-loading>기록을 비교하고 있어요…</div>')===false)return;const root=$('.rm-comparison');try{const stats=await request('/api/rm/comparison',{movementId:m.id});if(requestId!==comparisonRequest||!root.isConnected)return;const standing=rmStanding(stats),mine=best(id);root.innerHTML=!stats.participating?'<p class="empty">개인설정에서 회원 간 공개 동의와 순위 참여를 켜면 체육관 내 기록을 비교할 수 있어요.</p>':!mine?'<p class="empty">이 종목의 1RM을 먼저 등록해주세요.</p>':!standing?`<p class="empty">기록 보유 회원 ${Number(stats.total)||0}명 · 비교할 기록이 더 필요해요.</p>`:`<p class="rm-comparison-own">나의 최고 기록 <strong>${formatWeight(mine.lbs)} ${state.unit}</strong></p>${comparisonHeading(standing)}<div class="rm-position-chart" role="img" aria-label="${esc(standing.label)} · 기록 보유 회원 ${stats.total}명 기준"><div class="rm-position-zones"><span>하위</span><span>중위</span><span>상위</span></div><div class="rm-position-marker" style="--position:${standing.position}%"><span>나</span><i></i></div></div><p class="field-hint">기록 보유 회원 ${stats.total}명 기준 · 회원별 최고 기록 1개<br>같은 중량은 같은 백분위로 표시해요. 체중 보정 없이 중량으로 비교합니다.${stats.total<5?'<br>비교 인원이 적어 백분위가 크게 달라질 수 있어요.':''}</p>`;}catch(error){if(root.isConnected)root.textContent=error.message;}}
function accountRetentionNotice(member){if(member.approved_at||member.status==='approved')return '';const start=member.rejected_at||member.created_at;if(!start)return '';const due=new Date(Date.parse(start)+30*86400000),day=kstDate(due);return `<p class="account-retention ${+due<=+serverNow()?'overdue':''}">${member.rejected_at?'승인 거절':'승인 대기'} 계정 · ${esc(day)}까지 삭제${member.age_over_14?'':' · 만 14세 이상 확인 필요'}</p>`;}
function adminAccountDelete(id){if(viewer?.role!=='admin'||memberPreview||id===viewer.id)return;const member=state.members.find(m=>m.id===id);if(!member)return;modal('회원 계정 삭제',`<p><strong>${esc(member.name)}</strong> 회원의 로그인 계정과 개인 기록을 삭제합니다.</p><p class="danger-text">계정을 삭제하면 보유 포인트와 쿠폰이 모두 소멸하며, 복구할 수 없습니다.</p><form id="admin-account-delete-form" data-id="${esc(id)}" data-request-id="${crypto.randomUUID()}"><label class="field">삭제할 회원 이름을 그대로 입력해주세요<input name="confirmedName" required autocomplete="off" maxlength="40"></label><label class="checkbox-label"><input type="checkbox" name="confirmed" required>삭제 내용을 확인했습니다.</label><button class="btn danger-button full">계정 영구 삭제</button><p class="form-error" role="status"></p></form>`);}
function privacySetupPage(){return `<section class="panel push-welcome privacy-welcome privacy-compact"><div class="privacy-welcome-heading"><h1>개인정보 안내</h1>${privacySettingsOpen?`<button type="button" class="icon-control" data-action="privacy-settings-close" aria-label="개인정보 안내 닫기">${icon('close')}</button>`:''}</div><p class="privacy-intro">필수 정보와 회원 간 공개 범위를 확인해주세요.</p>${privacyConsentOverview()}<form id="privacy-accept-form">${genderField(viewer?.gender)}<label class="checkbox-label"><input type="checkbox" name="ageOver14" required ${viewer?.age_over_14?'checked':''}><span>[필수] 만 14세 이상입니다.</span></label><label class="checkbox-label"><input type="checkbox" name="privacy" required ${viewer?.privacy_version===PRIVACY_VERSION?'checked':''}><span>[필수] 개인정보 수집·이용 동의<small>동의하지 않으면 회원 서비스를 이용할 수 없어요.</small></span></label><label class="checkbox-label"><input type="checkbox" name="disclosure" ${viewer?.disclosure_consent?'checked':''}><span>[선택] 회원 간 공개 동의<small>실명·공개 기록·글·사진을 승인된 회원에게 제공해요. 거부해도 기본 기능을 이용할 수 있어요.</small></span></label><button class="btn primary full">${privacySettingsOpen?'변경 내용 저장':'동의하고 계속'}</button><p class="form-error" role="status"></p></form><div class="privacy-account-links"><button type="button" class="link" data-action="logout">로그아웃</button><button type="button" class="link" data-action="withdrawal">동의하지 않고 계정 삭제</button></div></section>`;}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.rmCompare)showRmComparison(b.dataset.rmCompare);if(b.dataset.adminAccountDelete)adminAccountDelete(b.dataset.adminAccountDelete);});
document.addEventListener('submit',async event=>{const f=event.target;if(!['privacy-accept-form','admin-account-delete-form'].includes(f.id))return;event.preventDefault();if(!f.reportValidity())return;const finish=beginFormSubmit(f);if(!finish)return;try{if(f.id==='privacy-accept-form'){await request('/api/privacy/accept',{version:PRIVACY_VERSION,gender:f.elements.gender.value,ageOver14:f.elements.ageOver14.checked,disclosure:f.elements.disclosure.checked});privacyReviewPending=false;unsaved.track(f);page=privacySettingsOpen?'settings':'home';privacySettingsOpen=false;history.replaceState(null,'','#'+page);await loadServer(false);}else{const target=state.members.find(m=>m.id===f.dataset.id);if(!target||f.elements.confirmedName.value!==target.name)throw Error('삭제할 회원 이름을 정확히 입력해주세요.');await request('/api/members/delete',{id:target.id,requestId:f.dataset.requestId,confirmed:true,confirmedName:f.elements.confirmedName.value});unsaved.track(f);if(f.isConnected&&f.closest('dialog')?.open)close(true);await loadServer(false);toast('회원 계정과 보유 포인트·쿠폰을 삭제했어요.');}}catch(error){f.querySelector('[role=status]').textContent=error.message;}finally{finish();}});

Object.assign(actions,{'privacy-settings':()=>{if(!unsaved.allow())return;privacySettingsOpen=true;go('privacy-setup');scrollAppTo(0,0);},'privacy-settings-close':()=>{if(go('settings')){privacySettingsOpen=false;render();}}});

function mountLibraryCategories(){libraryPager=mountCategoryPages($('#library-cards .category-pages'),{selected:libraryCategory,onCategory:id=>{libraryCategory=id;if($('#library-category'))$('#library-category').value=id;}});}
function mountRmCategories(){mountCategoryPages($('#main .category-pages'),{selected:rmCategory,onCategory:id=>rmCategory=id});}
function mountMemberPages(){const root=$('.member-pages');if(root)mountSwipePages(root,{page:memberPage,onPage:index=>memberPage=index});}
function confirmMembershipEventDelete(eventId,memberId){if(!coach||memberPreview)return;const event=membershipEvents.find(x=>x.id===eventId&&x.user_id===memberId);if(!event)return;modal('관리 이력 삭제',`<p>선택한 변경 이력만 삭제할까요? 실제 회원권과 출석 상태는 유지됩니다.</p><form id="membership-event-delete-form" data-event-id="${esc(eventId)}" data-member-id="${esc(memberId)}"><div class="form-footer"><button type="button" class="btn" data-member-detail="${esc(memberId)}">취소</button><button class="btn danger-button">이력 삭제</button></div><p class="form-error" role="status"></p></form>`);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-membership-event-delete]');if(b)confirmMembershipEventDelete(b.dataset.membershipEventDelete,b.dataset.memberId);});
document.addEventListener('submit',async event=>{const f=event.target;if(f.id!=='membership-event-delete-form')return;event.preventDefault();const finish=beginFormSubmit(f);if(!finish)return;try{await request('/api/membership/history/delete',{id:f.dataset.memberId,eventId:f.dataset.eventId,confirmed:true});unsaved.track(f);const current=f.isConnected&&f.closest('dialog')?.open;if(current)close(true);await loadServer(false);if(current)fullMemberDetail(f.dataset.memberId,'history');toast('관리 이력을 삭제했어요.');}catch(e){f.querySelector('[role=status]').textContent=e.message;}finally{finish();}});

async function refreshJoinAccess(id){if(!shared)return;const p=state.posts.find(x=>x.id===id);if(!p||p.category==='자유글')return;try{const value=await request('/api/posts/access',{id});if(!state.posts.includes(p))return;p.joinAccess=value;const root=$('[data-post-thread]');if(root?.dataset.postThread===id&&!postPending.has(id)){$('#thread-join').innerHTML=threadJoin(p);refreshPostControls(id);}}catch(e){const root=$('[data-post-thread]');if(root?.dataset.postThread===id){const status=root.querySelector('.thread-status');if(status)status.textContent='참여 가능 상태를 확인하지 못했어요. 다시 열어 확인해주세요.';}}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-join-access-refresh]');if(b)refreshJoinAccess(b.dataset.joinAccessRefresh);});

function overdueMembers(){return state.members.filter(m=>!m.approved_at&&m.status!=='approved'&&m.created_at&&Date.parse(m.rejected_at||m.created_at)+30*86400000<=+serverNow()).length;}

document.addEventListener('change',e=>{if(e.target.matches('#member-role-form [name=role]'))e.target.form.querySelector('.coach-permissions').hidden=e.target.value!=='coach';});

function refreshMeetupLifecycle(){
 if(viewer?.status!=='approved')return;
 if(page==='community')render();else{updateHomeHeader();nav();}
 const root=$('[data-post-thread]');if(!root)return;const p=state.posts.find(x=>x.id===root.dataset.postThread);if(!p)return;const life=meetupLifecycle(p,serverNow());
 if(life.expired){if(!unsaved.dirty(root)){close(true);toast('보관 기간이 지나 운동 번개 게시글이 삭제됐어요.');}else{root.querySelector('.thread-status').textContent='보관 기간이 지나 삭제된 글이에요. 작성 중인 댓글은 복사해 보관해주세요.';root.querySelectorAll('button').forEach(b=>b.disabled=true);}return;}
 root.classList.toggle('is-meetup-closed',life.closed);root.querySelector('.meetup-content').inert=life.closed;root.querySelector('[data-meetup-status]').innerHTML=life.closed?'<span class="meetup-closed-badge">마감</span>':'';root.querySelector('#thread-join').innerHTML=threadJoin(p);refreshPostControls(p.id);
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshMeetupLifecycle();});
